package media

import (
	"encoding/hex"
	"strconv"
)

// CIDv1 grammar (design §12.1; frontend chain/cid.ts is the twin):
// multibase 'b' (RFC 4648 base32, lower case, no padding) over exactly
// 0x01 · codec · 0x12 · 0x20 · digest[32], codec 0x55 (raw) or 0x70
// (dag-pb). That is 36 bytes = 58 base32 characters + 'b'. The unused two
// trailing bits must be zero, so every CID has exactly one spelling. CIDv0
// ("Qm…"), upper case, other bases, codecs or hash functions are refused.

const (
	b32Alphabet = "abcdefghijklmnopqrstuvwxyz234567"
	cidBytes    = 36
	cidChars    = 58 // ceil(36*8/5)
	mhSha256    = 0x12
	digestLen   = 32
)

// ParseCIDv1 returns the codec (CodecRaw or CodecDagPB) and the sha2-256
// digest as lower-case hex.
func ParseCIDv1(s string) (codec int, digestHex string, err error) {
	if s == "" {
		return 0, "", mediaErr("cid: empty")
	}
	if len(s) >= 2 && s[0] == 'Q' && s[1] == 'm' {
		return 0, "", mediaErr("cid: CIDv0 is not accepted; convert it to CIDv1")
	}
	if s[0] != 'b' {
		return 0, "", mediaErr("cid: multibase must be 'b' (base32 lower case)")
	}
	if len(s) != cidChars+1 {
		return 0, "", mediaErr("cid: expected " + strconv.Itoa(cidChars+1) + " characters, got " + strconv.Itoa(len(s)))
	}
	bz, derr := base32Decode(s[1:])
	if derr != nil {
		return 0, "", derr
	}
	if len(bz) != cidBytes {
		return 0, "", mediaErr("cid: wrong length")
	}
	if bz[0] != 1 {
		return 0, "", mediaErr("cid: version must be 1")
	}
	c := int(bz[1])
	if c != CodecRaw && c != CodecDagPB {
		return 0, "", mediaErr("cid: codec must be raw (0x55) or dag-pb (0x70)")
	}
	if bz[2] != mhSha256 || bz[3] != digestLen {
		return 0, "", mediaErr("cid: multihash must be sha2-256")
	}
	return c, hex.EncodeToString(bz[4:]), nil
}

// CIDFromDigest is the inverse of ParseCIDv1. It panics on an unsupported
// codec or a digest that is not 64 lower-case hex characters.
func CIDFromDigest(codec int, digestHex string) string {
	if codec != CodecRaw && codec != CodecDagPB {
		panic("media: cid: unsupported codec")
	}
	d, ok := Raw32(digestHex)
	if !ok {
		panic("media: cid: digest must be 64 lower-case hex characters")
	}
	bz := make([]byte, 0, cidBytes)
	bz = append(bz, 1, byte(codec), mhSha256, digestLen)
	bz = append(bz, d...)
	return "b" + base32Encode(bz)
}

// IsHex32 reports whether s is exactly 64 lower-case hex characters.
func IsHex32(s string) bool {
	_, ok := Raw32(s)
	return ok
}

// Raw32 decodes exactly 64 lower-case hex characters into 32 raw bytes
// (one pass, table lookups: VM loops cost ~5k gas per character).
func Raw32(s string) (string, bool) {
	if len(s) != 64 {
		return "", false
	}
	out := make([]byte, 32)
	for i := 0; i < 32; i++ {
		hi, lo := hexRev[s[2*i]], hexRev[s[2*i+1]]
		if hi > 15 || lo > 15 {
			return "", false
		}
		out[i] = hi<<4 | lo
	}
	return string(out), true
}

// hexRev and b32Rev map a byte to its digit value, 0xff when it is not a
// lower-case hex / base32 digit.
const (
	hexRev = "\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x0a\x0b\x0c\x0d\x0e\x0f\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff"
	b32Rev = "\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x1a\x1b\x1c\x1d\x1e\x1f\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f\x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff\xff"
)

func base32Encode(bz []byte) string {
	out := make([]byte, 0, (len(bz)*8+4)/5)
	var buf uint32
	bits := uint(0)
	for _, b := range bz {
		buf = buf<<8 | uint32(b)
		bits += 8
		for bits >= 5 {
			bits -= 5
			out = append(out, b32Alphabet[(buf>>bits)&31])
		}
		buf &= (1 << bits) - 1
	}
	if bits > 0 {
		out = append(out, b32Alphabet[(buf<<(5-bits))&31])
	}
	return string(out)
}

// base32Decode is strict: lower-case alphabet only, and the unused
// trailing bits must be zero.
func base32Decode(s string) ([]byte, error) {
	out := make([]byte, 0, len(s)*5/8)
	var buf uint32
	bits := uint(0)
	for i := 0; i < len(s); i++ {
		v := b32Rev[s[i]]
		if v > 31 {
			return nil, mediaErr("cid: invalid base32 character " + strconv.Quote(s[i:i+1]))
		}
		buf = buf<<5 | uint32(v)
		bits += 5
		if bits >= 8 {
			bits -= 8
			out = append(out, byte(buf>>bits))
			buf &= (1 << bits) - 1
		}
	}
	if bits >= 5 || buf != 0 {
		return nil, mediaErr("cid: non-canonical base32 padding bits")
	}
	return out, nil
}

package media

import (
	"strconv"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// CheckImage checks a complete file against its declared type: the magic
// bytes and the header's pixel dimensions (each 1..MaxDim, the
// decompression-bomb guard). SVG has no header dimensions (w, h = 0) and
// must pass safe.AssertSVG with the on-chain cap MaxSVGBytes (§0a), the same
// allowlist core applies to every render. Nothing else of a raster file is
// parsed: raster bytes are only ever shown through <img> (SA-M3).
func CheckImage(mime int, data string) (w, h int, err error) {
	switch mime {
	case MimeSVG:
		if err := safe.AssertSVG(data, MaxSVGBytes); err != nil {
			return 0, 0, err
		}
		return 0, 0, nil
	case MimePNG:
		w, h, err = pngDims(data)
	case MimeWebP:
		w, h, err = webpDims(data)
	case MimeJPEG:
		w, h, err = jpegDims(data)
	case MimeGIF:
		w, h, err = gifDims(data)
	default:
		return 0, 0, mediaErr("unknown media type " + strconv.Itoa(mime))
	}
	if err != nil {
		return 0, 0, err
	}
	if w < 1 || h < 1 || w > MaxDim || h > MaxDim {
		return 0, 0, mediaErr(MimeName(mime) + ": dimensions " + strconv.Itoa(w) + "x" + strconv.Itoa(h) +
			" outside 1.." + strconv.Itoa(MaxDim))
	}
	return w, h, nil
}

func be16(s string, i int) int { return int(s[i])<<8 | int(s[i+1]) }
func le16(s string, i int) int { return int(s[i]) | int(s[i+1])<<8 }
func le24(s string, i int) int { return int(s[i]) | int(s[i+1])<<8 | int(s[i+2])<<16 }
func be32(s string, i int) int64 {
	return int64(s[i])<<24 | int64(s[i+1])<<16 | int64(s[i+2])<<8 | int64(s[i+3])
}
func le32(s string, i int) int64 {
	return int64(s[i]) | int64(s[i+1])<<8 | int64(s[i+2])<<16 | int64(s[i+3])<<24
}

// pngDims: signature, then the IHDR chunk (length 13) with big-endian
// width and height. The 4-byte CRC after IHDR must be present.
func pngDims(s string) (int, int, error) {
	if len(s) < 33 || s[:8] != "\x89PNG\r\n\x1a\n" {
		return 0, 0, mediaErr("png: bad signature or truncated header")
	}
	if be32(s, 8) != 13 || s[12:16] != "IHDR" {
		return 0, 0, mediaErr("png: first chunk must be IHDR")
	}
	return int(be32(s, 16)), int(be32(s, 20)), nil
}

// webpDims: RIFF container whose size field covers the whole file, form
// type WEBP, then one of the three bitstream headers.
func webpDims(s string) (int, int, error) {
	if len(s) < 30 || s[:4] != "RIFF" || s[8:12] != "WEBP" {
		return 0, 0, mediaErr("webp: bad RIFF/WEBP header or truncated")
	}
	if le32(s, 4)+8 != int64(len(s)) {
		return 0, 0, mediaErr("webp: RIFF size does not match the file size")
	}
	switch s[12:16] {
	case "VP8 ": // lossy: 3-byte frame tag, start code 9d 01 2a, 14-bit dims
		if s[23:26] != "\x9d\x01\x2a" {
			return 0, 0, mediaErr("webp: bad VP8 start code")
		}
		return le16(s, 26) & 0x3fff, le16(s, 28) & 0x3fff, nil
	case "VP8L": // lossless: signature 0x2f, 14-bit width-1 and height-1
		if s[20] != 0x2f {
			return 0, 0, mediaErr("webp: bad VP8L signature")
		}
		bits := le32(s, 21)
		return int(bits&0x3fff) + 1, int((bits>>14)&0x3fff) + 1, nil
	case "VP8X": // extended: 24-bit canvas width-1 and height-1
		return le24(s, 24) + 1, le24(s, 27) + 1, nil
	}
	return 0, 0, mediaErr("webp: unknown bitstream chunk")
}

// jpegDims walks the marker segments after SOI up to the first SOFn
// (C0..CF except C4 DHT, C8 JPG, CC DAC). Reaching SOS or EOI first, or
// running out of bytes, is an error.
func jpegDims(s string) (int, int, error) {
	if len(s) < 4 || s[0] != 0xff || s[1] != 0xd8 || s[2] != 0xff {
		return 0, 0, mediaErr("jpeg: bad SOI")
	}
	i := 2
	for i < len(s) {
		if s[i] != 0xff {
			return 0, 0, mediaErr("jpeg: expected a marker at byte " + strconv.Itoa(i))
		}
		for i < len(s) && s[i] == 0xff { // fill bytes
			i++
		}
		if i >= len(s) {
			break
		}
		m := s[i]
		i++
		switch {
		case m == 0xd8 || m == 0x01 || (m >= 0xd0 && m <= 0xd7):
			continue // standalone markers
		case m == 0xd9 || m == 0xda:
			return 0, 0, mediaErr("jpeg: no frame header before scan data")
		}
		if i+2 > len(s) {
			break
		}
		n := be16(s, i)
		if n < 2 || i+n > len(s) {
			return 0, 0, mediaErr("jpeg: bad segment length")
		}
		if m >= 0xc0 && m <= 0xcf && m != 0xc4 && m != 0xc8 && m != 0xcc {
			if n < 8 {
				return 0, 0, mediaErr("jpeg: short frame header")
			}
			return be16(s, i+5), be16(s, i+3), nil // width after height
		}
		i += n
	}
	return 0, 0, mediaErr("jpeg: truncated before the frame header")
}

func gifDims(s string) (int, int, error) {
	if len(s) < 13 || (s[:6] != "GIF87a" && s[:6] != "GIF89a") {
		return 0, 0, mediaErr("gif: bad signature or truncated")
	}
	return le16(s, 6), le16(s, 8), nil
}

// Package media is the pure half of Sinopia's uploaded collections
// (docs/uploaded-collections.md §5.1, §0a): media kinds and types, the CIDv1
// grammar the platform accepts, image header checks, and the salt-keyed
// permutation that assigns tokens to artworks. It has no state; the asset
// store (r/…/assets/v1), the upload engine (r/…/engines/upload) and the
// frontend (chain/cid.ts, chain/perm.ts) share these definitions, pinned by
// the golden vectors in docs/test-vectors/upload-v1.json.
package media

import (
	"errors"
	"strconv"
)

// Storage kinds of one artwork.
const (
	KindChain      = 1 // bytes stored in assets/v1
	KindIPFSRaw    = 2 // raw-leaf CIDv1: the CID's digest is the file's sha256 (checked on chain)
	KindIPFSUnixFS = 3 // dag-pb CIDv1: digest of the root node, file sha256 stored separately
)

// Media types. GIF is defined for completeness but refused by ParseMime
// (decision D5: svg, png, webp, jpeg only).
const (
	MimeSVG  = 1
	MimePNG  = 2
	MimeWebP = 3
	MimeJPEG = 4
	MimeGIF  = 5
)

// Limits (decision D4 and design §4).
const (
	MaxDim         = 4096   // px per side, decompression-bomb guard
	MaxSVGBytes    = 16384  // on-chain SVG: AssertSVG costs ~30-50k gas/B (WP0)
	MaxRasterBytes = 262144 // on-chain png/webp/jpeg per artwork
	MaxIPFSRaw     = 1 << 20  // single raw block
	MaxIPFSUnixFS  = 50 << 20 // declared; the frontend enforces it while streaming
)

// CID codecs.
const (
	CodecRaw   = 0x55
	CodecDagPB = 0x70
)

// PermDomain separates the permutation key from every other platform hash
// (under safe.Domain "art").
const PermDomain = "art|upload|perm|v1|"

// Artwork is one record of a store as plain data. It crosses realm
// boundaries as a copy and never points into store state.
type Artwork struct {
	Index                            int64
	Kind, Mime                       int
	Size, Have, Editions, SlotEnd    int64
	SHA256, Digest, CID, Title, Tier string
	Traits                           []string // one value per store trait type ("" = none)
	Complete                         bool
	// JSON escaped once by the store (filled by assets/v1 reads, "" otherwise):
	// TierJSON is the tier name as a JSON string ("" = no tier); TraitsJSON the
	// creator traits as comma-joined {"trait_type":…,"value":…} items in store
	// order ("" = none). Lets token reads avoid per-call escaping (review UP-M1).
	TierJSON, TraitsJSON string
}

// SlotStart is the first slot of the artwork's range [SlotStart, SlotEnd).
func (a Artwork) SlotStart() int64 { return a.SlotEnd - a.Editions }

// StoreInfo is a store's header as plain data.
type StoreInfo struct {
	ID                                             string
	Owner                                          address
	Label                                          string
	Sealed                                         bool
	SealedHeight                                   int64
	Artworks, Slots, OnchainN, IPFSN, OnchainBytes int64
	TraitTypes, Tiers                              []string
}

// MimeType is the IANA type of a media constant ("" for an unknown one).
func MimeType(m int) string {
	switch m {
	case MimeSVG:
		return "image/svg+xml"
	case MimePNG:
		return "image/png"
	case MimeWebP:
		return "image/webp"
	case MimeJPEG:
		return "image/jpeg"
	case MimeGIF:
		return "image/gif"
	}
	return ""
}

// MimeName is the short name ParseMime accepts ("svg", "png", …).
func MimeName(m int) string {
	switch m {
	case MimeSVG:
		return "svg"
	case MimePNG:
		return "png"
	case MimeWebP:
		return "webp"
	case MimeJPEG:
		return "jpeg"
	case MimeGIF:
		return "gif"
	}
	return ""
}

// ParseMime maps "svg" | "png" | "webp" | "jpeg" to its constant and panics
// on anything else, "gif" included (D5).
func ParseMime(s string) int {
	switch s {
	case "svg":
		return MimeSVG
	case "png":
		return MimePNG
	case "webp":
		return MimeWebP
	case "jpeg":
		return MimeJPEG
	case "gif":
		panic("mime: gif is not supported (svg, png, webp, jpeg)")
	}
	panic("mime: must be svg, png, webp or jpeg, got " + strconv.Quote(s))
}

// KindName is "chain" or "ipfs".
func KindName(k int) string {
	switch k {
	case KindChain:
		return "chain"
	case KindIPFSRaw, KindIPFSUnixFS:
		return "ipfs"
	}
	return ""
}

// MaxBytes is the size cap of one artwork of this kind and type.
func MaxBytes(kind, mime int) int64 {
	switch kind {
	case KindChain:
		if mime == MimeSVG {
			return MaxSVGBytes
		}
		return MaxRasterBytes
	case KindIPFSRaw:
		return MaxIPFSRaw
	case KindIPFSUnixFS:
		return MaxIPFSUnixFS
	}
	return 0
}

// Badge is a store's storage badge from its counters (design §9):
// "onchain", "ipfs", "mixed", or "empty" for a store without artworks.
func Badge(onchainN, ipfsN int64) string {
	switch {
	case onchainN == 0 && ipfsN == 0:
		return "empty"
	case ipfsN == 0:
		return "onchain"
	case onchainN == 0:
		return "ipfs"
	}
	return "mixed"
}

func mediaErr(msg string) error { return errors.New("media: " + msg) }

package media

import (
	"crypto/sha256"
	"strconv"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Token → artwork assignment (design §7; frontend chain/perm.ts is the twin).
//
//	K         = sha256hex(PermDomain + collectionID + "|" + salt)
//	slot(tid) = Permute(K, slots, tid-1)    (single-artwork store: tid-1)
//
// The salt exists only once the collection is Final (commit–reveal v2), so
// nobody, the creator included, knows any token's slot before every token
// was sold and both secrets were revealed.

// PermKey is the permutation key of collection cid with its final salt.
func PermKey(cid, salt string) string {
	return safe.Sha256Hex(PermDomain + cid + "|" + salt)
}

// Permute is a bijection on [0, n): a 4-round Feistel network over b bits
// (b = bitlen(n-1) rounded up to an even number ≥ 2, so 2^b < 4n) with cycle
// walking. Round function: F = big-endian uint64 of the first 8 bytes of
// sha256(keyHex + "|" + r + "|" + R), masked to h = b/2 bits, with r and R
// in decimal. It panics unless 1 ≤ n and 0 ≤ x < n.
func Permute(keyHex string, n, x int64) int64 {
	if n < 1 || x < 0 || x >= n {
		panic("media: permute: need 0 <= x < n")
	}
	if n == 1 {
		return 0
	}
	b := bitLen(uint64(n - 1))
	if b < 2 {
		b = 2
	}
	if b%2 == 1 {
		b++
	}
	h := uint(b / 2)
	mask := uint64(1)<<h - 1
	prefix := keyHex + "|"
	v := uint64(x)
	// The walk stays on x's cycle, which contains x itself (< n), so it
	// ends; the bound only guards against a broken hash.
	for walk := 0; walk < 1<<uint(b); walk++ {
		l, r := v>>h, v&mask
		for round := 0; round < 4; round++ {
			f := roundF(prefix+strconv.Itoa(round)+"|", r) & mask
			l, r = r, l^f
		}
		v = l<<h | r
		if v < uint64(n) {
			return int64(v)
		}
	}
	panic("media: permute: cycle walk did not terminate")
}

func roundF(prefix string, r uint64) uint64 {
	sum := sha256.Sum256([]byte(prefix + strconv.FormatUint(r, 10)))
	return uint64(sum[0])<<56 | uint64(sum[1])<<48 | uint64(sum[2])<<40 | uint64(sum[3])<<32 |
		uint64(sum[4])<<24 | uint64(sum[5])<<16 | uint64(sum[6])<<8 | uint64(sum[7])
}

func bitLen(v uint64) int {
	n := 0
	for v > 0 {
		n++
		v >>= 1
	}
	return n
}

// Slot is the slot of token tid (1-based) in a store of `artworks`
// artworks and `slots` slots: the identity tid-1 for a single-artwork store
// (1/1 and editions: "Edition 3 of 50"), Permute(K, slots, tid-1) otherwise.
func Slot(keyHex string, artworks, slots, tid int64) int64 {
	if tid < 1 || tid > slots {
		panic("media: slot: token id out of range")
	}
	if artworks == 1 {
		return tid - 1
	}
	return Permute(keyHex, slots, tid-1)
}

// Package assets is Sinopia's immutable asset store for uploaded
// collections (docs/uploaded-collections.md §4–§6, §0a). An artist creates a
// store, declares artworks (on-chain bytes or IPFS CIDs, each with its
// sha256, editions, a creator-assigned tier and trait values), uploads the
// on-chain bytes in chunks, and seals it. A sealed store never changes: the
// upload engine (r/…/engines/upload) binds one sealed store to one Draft
// collection and reads its art from here.
//
// Guarantees (design §14):
//   - only the store's owner writes, and only from a wallet (direct
//     MsgCall, IsUserCall); nothing here accepts or holds coins;
//   - a store is Draft until Seal, which is irreversible: records, titles,
//     dictionaries and bytes are immutable afterwards;
//   - an "on-chain" artwork is complete only when every byte is stored,
//     its sha256 equals the declared one and media.CheckImage passed
//     (magic + dimensions; SVG through safe.AssertSVG, 16 KiB cap);
//   - an "ipfs" artwork always says ipfs; a raw CID's digest is checked
//     against the declared sha256 on chain;
//   - every user string passed safe.AssertText; JSON goes through
//     safe.JSONWriter.
//
// Storage is paid by the owner who writes it, and only the owner can free
// Draft data (Truncate), so refunds go back to the payer (T8).
package assets

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Limits (design §4 as amended by §0a / D4, and by the UP-M1 review fix:
// every read of the largest store these limits allow must stay far below
// the 3B query gas cap; worst cases are locked by zz_worst_gas_test.gno in
// r/reader).
const (
	MaxArtworks          = 10_000 // = core MaxSupplyCap
	MaxSlots             = 10_000 // Bind requires slots == maxSupply
	MaxEditions          = 10_000
	MaxTraitTypes        = 8   // core-path manifest slots "Trait 1".."Trait 8" (was 16)
	MaxTiers             = 8
	MaxDictValues        = 100 // distinct values per trait type (was 255)
	MaxStoreValues       = 255 // distinct values over all trait types of a store (new; u8 id + 1 in a record)
	MaxNameLen           = 20  // trait type and tier names
	MaxValueLen          = 32  // trait values (was 40)
	MaxTitleLen          = 64  // artwork titles (= engine.MaxTraitLen)
	MaxLabelLen          = 64
	MaxStoreOnchainBytes = 4 << 20 // ~430 GNOT of deposit at 100 ugnot/B
	MaxChunk             = 262_144 // per AppendBytes call; a tx carries ~540 KB raw (WP0)
	SegmentBytes         = 32_768  // byte-log value size (~6% key overhead, measured)
	MaxBatch             = 100     // records per AddArtworks
	MaxPage              = 20      // Artworks page (was 50)
)

const zero32 = "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00"

// reserved trait type names: the adapter adds these itself (case-insensitive).
var reservedTraitTypes = []string{"tier", "edition", "storage", "status", "artwork"}

type store struct {
	id            int64
	owner         address
	label         string
	sealed        bool
	createdHeight int64
	sealedHeight  int64
	traitTypes    []string // order = slot order ("Trait k")
	tiers         []string // ordered low -> high
	n             int64    // artworks
	slots         int64    // sum of editions
	onchainN      int64
	ipfsN         int64
	onchainBytes  int64 // declared on-chain bytes (sum of chain sizes)
	logLen        int64 // bytes received in the byte log
	buckets       avl.Tree // safe.PadInt(idx/bucketSize, 3) -> *bucket
	log           avl.Tree // safe.PadInt(segment, 3) -> string (<= SegmentBytes)
	shas          *shaIndex
	// Set composition and names for reads that never loop over artworks and
	// never escape at read time (review UP-M1). Three slice objects per store.
	names     []string    // JSON of the trait types, then of the tiers (escaped once, at NewStore)
	dict      []dictEntry // every distinct trait value, in first-use order; a record stores id + 1
	cnt       []int64     // counters: [0..t] tier artworks, [t+1..2t+1] tier slots (index 0 = untiered),
	                      // then per dict entry i: [base+2i] artworks, [base+2i+1] slots (base = 2t+2)
	perType   [MaxTraitTypes]int
	chainIdx  string // indexes of the on-chain artworks, u32 big-endian each, in order
	chainDone int64  // how many of them are complete (bytes arrive in artwork order)
}

// dictEntry is one distinct trait value of a store: its trait type, the
// value and its JSON (escaped once, when first used).
type dictEntry struct {
	k  int
	v  string
	js string
}

func (s *store) cntBase() int { return 2*len(s.tiers) + 2 }

// count counts one record in (sign +1) or out (sign -1).
func (s *store) count(r *record, sign int64) {
	ed := r.editions * sign
	t := len(s.tiers)
	s.cnt[r.tier] += sign
	s.cnt[t+1+r.tier] += ed
	base := s.cntBase()
	for k := range s.traitTypes {
		if id := r.traits[k]; id > 0 {
			s.cnt[base+2*(id-1)] += sign
			s.cnt[base+2*(id-1)+1] += ed
		}
	}
}

// shaIndex is the sorted list of every artwork's raw sha256 (32 B each),
// one object per store: duplicate detection without one avl key (~2 KB)
// per artwork.
type shaIndex struct {
	s string
}

var (
	stores     avl.Tree // safe.PadInt(id, 10) -> *store
	storeCount int64
)

func storeKey(id int64) string { return safe.PadInt(id, 10) }

func bucketKey(b int64) string { return safe.PadInt(b, 3) }

func mustStore(storeID string) *store {
	v := stores.Get(storeKey(safe.ParseID("store", storeID)))
	if v == nil {
		panic("unknown store " + strconv.Quote(storeID))
	}
	return v.(*store)
}

func (s *store) idStr() string { return strconv.FormatInt(s.id, 10) }

// assertWallet: every write comes straight from a wallet's MsgCall and
// carries no coins.
func assertWallet(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("asset stores are written by their owner's wallet only (direct call)")
	}
	if !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func ownedDraft(cur realm, storeID string) *store {
	assertWallet(cur)
	s := mustStore(storeID)
	if cur.Previous().Address() != s.owner {
		panic("only the store owner " + s.owner.String() + " can change store " + storeID)
	}
	if s.sealed {
		panic("store " + storeID + " is sealed")
	}
	return s
}

// --- writes ------------------------------------------------------------------

// NewStore creates an empty Draft store owned by the calling wallet.
// traitTypes and tiers are '|'-separated name lists ("" = none): at most 16
// trait types and 8 tiers (tiers ordered low -> high), names 1..20 bytes,
// no ':' and no leading/trailing space, unique ignoring case; "Tier",
// "Edition", "Storage", "Status" and "Artwork" are reserved trait types.
// Returns the store id. Event StoreCreated{store, owner}.
func NewStore(cur realm, label, traitTypes, tiers string) string {
	assertWallet(cur)
	safe.AssertText("label", label, MaxLabelLen)
	tt := parseNames("traitTypes", traitTypes, MaxTraitTypes, true)
	ts := parseNames("tiers", tiers, MaxTiers, false)
	storeCount++
	s := &store{
		id:            storeCount,
		owner:         cur.Previous().Address(),
		label:         label,
		createdHeight: runtime.ChainHeight(),
		traitTypes:    tt,
		tiers:         ts,
		shas:          &shaIndex{},
		names:         append(jsonAll(tt), jsonAll(ts)...),
		cnt:           make([]int64, 2*len(ts)+2),
	}
	stores.Set(storeKey(s.id), s)
	chain.Emit("StoreCreated", "store", s.idStr(), "owner", s.owner.String())
	return s.idStr()
}

func jsonAll(xs []string) []string {
	out := make([]string, len(xs))
	for i, x := range xs {
		out[i] = jsonStr(x)
	}
	return out
}

// jsonStr is safe.JSONString (same bytes: '"' '\\' \n \r \t, '<' '>' '&',
// U+2028/9 and other controls escaped) without its per-character hex
// formatting, which made '<'-heavy text cost ~10x more (UP-M1).
func jsonStr(x string) string {
	plain := true
	for i := 0; i < len(x); i++ {
		c := x[i]
		if c < 0x20 || c == '"' || c == '\\' || c == '<' || c == '>' || c == '&' || c == 0x7f || c == 0xe2 {
			plain = false
			break
		}
	}
	if plain {
		return `"` + x + `"`
	}
	const hexd = "0123456789abcdef"
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range x {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '<':
			b.WriteString(`\u003c`)
		case '>':
			b.WriteString(`\u003e`)
		case '&':
			b.WriteString(`\u0026`)
		case 0x2028:
			b.WriteString(`\u2028`)
		case 0x2029:
			b.WriteString(`\u2029`)
		default:
			if r < 0x20 || r == 0x7f {
				b.WriteString(`\u00`)
				b.WriteByte(hexd[(r>>4)&0xf])
				b.WriteByte(hexd[r&0xf])
				continue
			}
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func parseNames(field, list string, max int, traits bool) []string {
	if list == "" {
		return []string{}
	}
	parts := strings.Split(list, "|")
	if len(parts) > max {
		panic(field + ": at most " + strconv.Itoa(max))
	}
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		safe.AssertNonEmptyText(field, p, MaxNameLen)
		if strings.Contains(p, ":") || strings.TrimSpace(p) != p {
			panic(field + ": " + strconv.Quote(p) + " may not contain ':' or leading/trailing spaces")
		}
		low := strings.ToLower(p)
		if traits {
			for _, r := range reservedTraitTypes {
				if low == r {
					panic(field + ": " + strconv.Quote(p) + " is reserved")
				}
			}
		}
		for _, prev := range out {
			if strings.ToLower(prev) == low {
				panic(field + ": duplicate " + strconv.Quote(p))
			}
		}
		out = append(out, p)
	}
	return out
}

// AddArtworks declares up to MaxBatch artworks, one per '\n'-separated line:
//
//	kind|mime|size|sha256|cid|editions|tier|title|v1|…|vN
//
// with exactly one value per trait type of the store (N = len(traitTypes)):
//   - kind "chain" | "ipfs"; mime "svg" | "png" | "webp" | "jpeg";
//   - size: decimal bytes, chain svg <= 16,384, chain raster <= 262,144,
//     ipfs raw <= 1 MiB, ipfs dag-pb <= 50 MiB; the store's on-chain total
//     stays <= 4 MiB;
//   - sha256: 64 lower-case hex of the file bytes, unique in the store
//     (use editions for copies);
//   - cid: "" for chain; for ipfs a CIDv1 (media.ParseCIDv1): raw codec ⇒
//     its digest must equal sha256 (verified binding), dag-pb ⇒ digest stored;
//   - editions 1..10,000 (the store's slots stay <= 10,000);
//   - tier "" or one of the store's tiers; title <= 64 bytes;
//   - values "" (none) or <= 32 bytes, no leading/trailing space; at most
//     100 distinct values per trait type and 255 over all types of a store.
//
// Returns "first-last" (0-based indexes). Event ArtworkAdded per line.
func AddArtworks(cur realm, storeID, batch string) string {
	s := ownedDraft(cur, storeID)
	if batch == "" {
		panic("batch: empty")
	}
	lines := split(batch, '\n')
	if len(lines) > MaxBatch {
		panic("batch: at most " + strconv.Itoa(MaxBatch) + " artworks per call")
	}
	if s.n+int64(len(lines)) > MaxArtworks {
		panic("store: at most " + strconv.Itoa(MaxArtworks) + " artworks")
	}
	first := s.n
	shas := make([]string, 0, len(lines))
	// per-call (type, value) -> id map, built once from the dictionary: a
	// line costs O(1) per trait instead of a scan of the values (UP-L1)
	var look map[string]int
	for i, line := range lines {
		f := split(line, '|')
		r, title := s.parseLine(i+1, f, &look)
		shas = append(shas, r.sha)
		s.appendRecord(&r, title)
		// the line's sha256 and CID are already canonical (strict parsers):
		// re-encoding them would cost ~1.5M gas per line for the same text
		chain.Emit("ArtworkAdded", "store", s.idStr(), "idx", strconv.FormatInt(s.n-1, 10),
			"kind", media.KindName(r.kind), "mime", media.MimeName(r.mime),
			"size", strconv.FormatInt(r.size, 10), "sha256", f[3], "cid", f[4],
			"editions", strconv.FormatInt(r.editions, 10), "tier", s.tierName(r.tier))
	}
	s.shas.insert(shas)
	return strconv.FormatInt(first, 10) + "-" + strconv.FormatInt(s.n-1, 10)
}

// split is strings.Split for a one-byte separator in a single pass (half
// the VM gas of strings.Split, which dominates a 100-line batch).
func split(s string, sep byte) []string {
	out := make([]string, 0, 16)
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] == sep {
			out = append(out, s[start:i])
			start = i + 1
		}
	}
	return append(out, s[start:])
}

func (s *store) parseLine(no int, f []string, look *map[string]int) (record, string) {
	at := "line " + strconv.Itoa(no) + ": "
	if want := 8 + len(s.traitTypes); len(f) != want {
		panic(at + "expected " + strconv.Itoa(want) + " '|'-separated fields, got " + strconv.Itoa(len(f)))
	}
	var r record
	switch f[0] {
	case "chain":
		r.kind = media.KindChain
	case "ipfs":
	default:
		panic(at + "kind must be chain or ipfs")
	}
	r.mime = parseMime(at, f[1])
	r.size = parseCount(at+"size", f[2], 1<<62)
	shaRaw, ok := media.Raw32(f[3])
	if !ok {
		panic(at + "sha256 must be 64 lower-case hex characters")
	}
	r.sha = shaRaw
	r.digest = zero32
	if r.kind == media.KindChain {
		if f[4] != "" {
			panic(at + "an on-chain artwork has no cid")
		}
	} else {
		codec, digest, err := media.ParseCIDv1(f[4])
		if err != nil {
			panic(at + err.Error())
		}
		if codec == media.CodecRaw {
			if digest != f[3] {
				panic(at + "a raw CID's digest must equal the file's sha256")
			}
			r.kind = media.KindIPFSRaw
		} else {
			r.kind = media.KindIPFSUnixFS
			r.digest, _ = media.Raw32(digest)
		}
	}
	if max := media.MaxBytes(r.kind, r.mime); r.size > max {
		panic(at + "size " + f[2] + " exceeds " + strconv.FormatInt(max, 10) + " bytes for this kind and type")
	}
	r.editions = parseCount(at+"editions", f[5], MaxEditions)
	if s.slots+r.editions > MaxSlots {
		panic(at + "the store would exceed " + strconv.Itoa(MaxSlots) + " slots (sum of editions)")
	}
	r.tier = s.tierIndex(at, f[6])
	title := f[7]
	safe.AssertText(at+"title", title, MaxTitleLen)
	for k := range s.traitTypes {
		r.traits[k] = s.dictIndex(at, k, f[8+k], look)
	}
	if r.kind == media.KindChain {
		if s.onchainBytes+r.size > MaxStoreOnchainBytes {
			panic(at + "the store would exceed " + strconv.Itoa(MaxStoreOnchainBytes) + " on-chain bytes")
		}
		r.logOff = s.onchainBytes
	} else {
		r.have = r.size
	}
	r.slotEnd = s.slots + r.editions
	return r, title
}

func parseMime(at, s string) (m int) {
	switch s {
	case "svg":
		return media.MimeSVG
	case "png":
		return media.MimePNG
	case "webp":
		return media.MimeWebP
	case "jpeg":
		return media.MimeJPEG
	}
	panic(at + "mime must be svg, png, webp or jpeg")
}

// parseCount parses a canonical positive decimal (no sign, no leading zero) <= max.
func parseCount(field, s string, max int64) int64 {
	if s == "" || len(s) > 19 || s[0] == '0' {
		panic(field + ": must be a positive decimal")
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			panic(field + ": must be a positive decimal")
		}
		n = n*10 + int64(c-'0')
		if n > max {
			panic(field + ": at most " + strconv.FormatInt(max, 10))
		}
	}
	return n
}

func (s *store) tierIndex(at, name string) int {
	if name == "" {
		return 0
	}
	for i, t := range s.tiers {
		if t == name {
			return i + 1
		}
	}
	panic(at + "unknown tier " + strconv.Quote(name))
}

func (s *store) tierName(i int) string {
	if i == 0 {
		return ""
	}
	return s.tiers[i-1]
}

func (s *store) dictIndex(at string, k int, v string, look *map[string]int) int {
	if v == "" {
		return 0
	}
	if *look == nil {
		m := make(map[string]int, len(s.dict))
		for i, e := range s.dict {
			m[strconv.Itoa(e.k)+"|"+e.v] = i + 1
		}
		*look = m
	}
	key := strconv.Itoa(k) + "|" + v
	if id, ok := (*look)[key]; ok {
		return id
	}
	// a new value: checked once, stored with its JSON and zero counters
	safe.AssertText(at+s.traitTypes[k], v, MaxValueLen)
	if strings.TrimSpace(v) != v {
		panic(at + s.traitTypes[k] + ": no leading or trailing spaces")
	}
	if s.perType[k] >= MaxDictValues {
		panic(at + s.traitTypes[k] + ": at most " + strconv.Itoa(MaxDictValues) + " distinct values")
	}
	if len(s.dict) >= MaxStoreValues {
		panic(at + "a store holds at most " + strconv.Itoa(MaxStoreValues) + " distinct trait values")
	}
	s.dict = append(s.dict, dictEntry{k: k, v: v, js: jsonStr(v)})
	s.cnt = append(s.cnt, 0, 0)
	s.perType[k]++
	(*look)[key] = len(s.dict)
	return len(s.dict)
}

func (s *store) appendRecord(r *record, title string) {
	k := bucketKey(s.n / bucketSize)
	var b *bucket
	if v := s.buckets.Get(k); v != nil {
		b = v.(*bucket)
	} else {
		b = &bucket{}
		s.buckets.Set(k, b)
	}
	b.rec += r.encode()
	b.titles += string([]byte{byte(len(title))}) + title
	if r.kind == media.KindChain {
		s.onchainN++
		s.onchainBytes += r.size
		s.chainIdx += u32(s.n)
	} else {
		s.ipfsN++
	}
	s.n++
	s.slots = r.slotEnd
	s.count(r, 1)
}

func u32(v int64) string {
	return string([]byte{byte(v >> 24), byte(v >> 16), byte(v >> 8), byte(v)})
}

// insert merges sorted-unique new digests into the index; any duplicate
// (inside the batch or with an earlier artwork) aborts the call.
func (x *shaIndex) insert(add []string) {
	for i := 1; i < len(add); i++ { // insertion sort, <= MaxBatch items
		for j := i; j > 0 && add[j] < add[j-1]; j-- {
			add[j], add[j-1] = add[j-1], add[j]
		}
	}
	for i := 1; i < len(add); i++ {
		if add[i] == add[i-1] {
			panic("sha256 " + hex.EncodeToString([]byte(add[i])) + " appears twice; use editions for copies")
		}
	}
	var b strings.Builder
	pos := 0
	for _, d := range add {
		at := x.search(d)
		if at < len(x.s) && x.s[at:at+32] == d {
			panic("sha256 " + hex.EncodeToString([]byte(d)) + " is already in this store; use editions for copies")
		}
		b.WriteString(x.s[pos:at])
		b.WriteString(d)
		pos = at
	}
	b.WriteString(x.s[pos:])
	x.s = b.String()
}

// remove drops the given digests (each present once).
func (x *shaIndex) remove(drop []string) {
	for _, d := range drop {
		at := x.search(d)
		if at < len(x.s) && x.s[at:at+32] == d {
			x.s = x.s[:at] + x.s[at+32:]
		}
	}
}

// search is the byte offset of the first entry >= d.
func (x *shaIndex) search(d string) int {
	lo, hi := 0, len(x.s)/32
	for lo < hi {
		mid := (lo + hi) / 2
		if x.s[mid*32:mid*32+32] < d {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo * 32
}

// AppendBytes stores the next chunk of an on-chain artwork. Bytes arrive
// in artwork order: idx must be the lowest incomplete on-chain artwork and
// offset its Have (resume = read Have). chunk is a []byte argument (the
// keeper decodes the MsgCall's base64 natively, WP0), 1..MaxChunk bytes.
// When the artwork is complete its sha256 must equal the declared one and
// media.CheckImage must pass, else the call panics and nothing is stored.
// Event ArtworkComplete{store, idx}.
func AppendBytes(cur realm, storeID string, idx, offset int64, chunk []byte) {
	s := ownedDraft(cur, storeID)
	if idx < 0 || idx >= s.n {
		panic("no artwork " + strconv.FormatInt(idx, 10) + " in store " + storeID)
	}
	b, i := s.bucketOf(idx)
	r := decodeRecord(b.raw(i))
	if r.kind != media.KindChain {
		panic("artwork " + strconv.FormatInt(idx, 10) + " is not stored on chain")
	}
	if r.complete() {
		panic("artwork " + strconv.FormatInt(idx, 10) + " is already complete")
	}
	if offset != r.have {
		panic("offset must equal have (" + strconv.FormatInt(r.have, 10) + ")")
	}
	if r.logOff+r.have != s.logLen {
		panic("upload the lowest incomplete on-chain artwork first")
	}
	n := int64(len(chunk))
	if n == 0 || n > MaxChunk {
		panic("chunk must be 1.." + strconv.Itoa(MaxChunk) + " bytes")
	}
	if r.have+n > r.size {
		panic("chunk exceeds the declared size (" + strconv.FormatInt(r.size-r.have, 10) + " bytes left)")
	}
	s.appendLog(string(chunk))
	r.have += n
	if r.complete() {
		data := s.readLog(r.logOff, r.size)
		sum := sha256.Sum256([]byte(data))
		if string(sum[:]) != r.sha {
			panic("sha256 mismatch: the uploaded bytes are not the declared file")
		}
		if _, _, err := media.CheckImage(r.mime, data); err != nil {
			panic("artwork " + strconv.FormatInt(idx, 10) + " rejected: " + err.Error())
		}
		s.chainDone++ // in-order uploads: idx was the next on-chain artwork
		chain.Emit("ArtworkComplete", "store", storeID, "idx", strconv.FormatInt(idx, 10))
	}
	b.setRaw(i, r.encode())
}

func (s *store) bucketOf(idx int64) (*bucket, int) {
	v := s.buckets.Get(bucketKey(idx / bucketSize))
	if v == nil {
		panic("assets: missing record bucket")
	}
	return v.(*bucket), int(idx % bucketSize)
}

func (s *store) appendLog(chunk string) {
	for len(chunk) > 0 {
		k := bucketKey(s.logLen / SegmentBytes)
		seg := ""
		if v := s.log.Get(k); v != nil {
			seg = v.(string)
		}
		n := SegmentBytes - len(seg)
		if n > len(chunk) {
			n = len(chunk)
		}
		s.log.Set(k, seg+chunk[:n])
		s.logLen += int64(n)
		chunk = chunk[n:]
	}
}

func (s *store) readLog(off, n int64) string {
	var b strings.Builder
	for n > 0 {
		seg := off / SegmentBytes
		v := s.log.Get(bucketKey(seg)).(string)
		lo := off - seg*SegmentBytes
		hi := int64(len(v))
		if hi-lo > n {
			hi = lo + n
		}
		b.WriteString(v[lo:hi])
		n -= hi - lo
		off += hi - lo
	}
	return b.String()
}

// cutLog shortens the byte log to newLen bytes (frees whole segments).
func (s *store) cutLog(newLen int64) {
	for s.logLen > newLen {
		seg := (s.logLen - 1) / SegmentBytes
		start := seg * SegmentBytes
		k := bucketKey(seg)
		if start >= newLen {
			s.log.Remove(k)
			s.logLen = start
			continue
		}
		v := s.log.Get(k).(string)
		s.log.Set(k, v[:newLen-start])
		s.logLen = newLen
	}
}

// Truncate drops artworks keep..n-1 of a Draft store and cuts the byte log
// back, freeing their storage (the chain refunds the signer, i.e. the owner
// who paid it). Trait values first used by dropped artworks stay in the
// dictionary (with zero counts; they still count towards MaxStoreValues).
// Event StoreTruncated{store, keep}.
func Truncate(cur realm, storeID string, keep int64) {
	s := ownedDraft(cur, storeID)
	if keep < 0 || keep >= s.n {
		panic("keep must be 0.." + strconv.FormatInt(s.n-1, 10))
	}
	cut := int64(-1)
	var dropped []string
	for idx := keep; idx < s.n; idx++ {
		b, i := s.bucketOf(idx)
		r := decodeRecord(b.raw(i))
		dropped = append(dropped, r.sha)
		s.count(&r, -1)
		if r.kind == media.KindChain {
			s.onchainN--
			if r.complete() {
				s.chainDone--
			}
			if cut < 0 {
				cut = r.logOff
			}
		} else {
			s.ipfsN--
		}
	}
	s.chainIdx = s.chainIdx[:s.onchainN*4]
	if cut >= 0 {
		s.onchainBytes = cut
		if s.logLen > cut {
			s.cutLog(cut)
		}
	}
	s.slots = 0
	if keep > 0 {
		b, i := s.bucketOf(keep - 1)
		s.slots = decodeRecord(b.raw(i)).slotEnd
	}
	last := (s.n - 1) / bucketSize
	kb := keep / bucketSize
	for bk := last; bk > kb; bk-- {
		s.buckets.Remove(bucketKey(bk))
	}
	if keep%bucketSize == 0 {
		s.buckets.Remove(bucketKey(kb))
	} else {
		v := s.buckets.Get(bucketKey(kb)).(*bucket)
		v.keep(int(keep % bucketSize))
	}
	s.n = keep
	s.shas.remove(dropped)
	chain.Emit("StoreTruncated", "store", storeID, "keep", strconv.FormatInt(keep, 10))
}

// Seal freezes a store for good. It needs at least one artwork and every
// on-chain artwork complete. Event StoreSealed{store, artworks, slots,
// onchainN, ipfsN, onchainBytes}.
func Seal(cur realm, storeID string) {
	s := ownedDraft(cur, storeID)
	if s.n == 0 {
		panic("a store needs at least one artwork to be sealed")
	}
	if s.logLen != s.onchainBytes {
		panic("on-chain artworks are incomplete: " + strconv.FormatInt(s.logLen, 10) + " of " +
			strconv.FormatInt(s.onchainBytes, 10) + " bytes uploaded")
	}
	s.sealed = true
	s.sealedHeight = runtime.ChainHeight()
	chain.Emit("StoreSealed", "store", storeID, "artworks", strconv.FormatInt(s.n, 10),
		"slots", strconv.FormatInt(s.slots, 10), "onchainN", strconv.FormatInt(s.onchainN, 10),
		"ipfsN", strconv.FormatInt(s.ipfsN, 10), "onchainBytes", strconv.FormatInt(s.onchainBytes, 10))
}

package assets

import (
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// Every function in this file is read-only. The artwork set of a store is
// public by design (D8: on-chain and plain IPFS art cannot be hidden); the
// site shows only the set composition before a collection's reveal.

func StoreCount() int64 { return storeCount }

// Info is the typed store header for other realms (a copy).
func Info(storeID string) media.StoreInfo {
	s := mustStore(storeID)
	return media.StoreInfo{
		ID:           s.idStr(),
		Owner:        s.owner,
		Label:        s.label,
		Sealed:       s.sealed,
		SealedHeight: s.sealedHeight,
		Artworks:     s.n,
		Slots:        s.slots,
		OnchainN:     s.onchainN,
		IPFSN:        s.ipfsN,
		OnchainBytes: s.onchainBytes,
		TraitTypes:   append([]string{}, s.traitTypes...),
		Tiers:        append([]string{}, s.tiers...),
	}
}

// Store is the store header as JSON: {id, owner, label, state, createdHeight,
// sealedHeight, artworks, slots, onchainN, ipfsN, onchainBytes, received,
// complete, nextUpload, badge, traitTypes, tiers}. received = on-chain bytes
// stored so far; nextUpload = index of the artwork AppendBytes expects next
// (-1 when every on-chain artwork is complete); badge = media.Badge.
func Store(storeID string) string {
	s := mustStore(storeID)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("id", s.idStr())
	w.StrField("owner", s.owner.String())
	w.StrField("label", s.label)
	if s.sealed {
		w.StrField("state", "sealed")
	} else {
		w.StrField("state", "draft")
	}
	w.IntField("createdHeight", s.createdHeight)
	w.IntField("sealedHeight", s.sealedHeight)
	w.IntField("artworks", s.n)
	w.IntField("slots", s.slots)
	w.IntField("onchainN", s.onchainN)
	w.IntField("ipfsN", s.ipfsN)
	w.IntField("onchainBytes", s.onchainBytes)
	w.IntField("received", s.logLen)
	w.BoolField("complete", s.logLen == s.onchainBytes)
	w.IntField("nextUpload", s.nextUpload())
	w.StrField("badge", media.Badge(s.onchainN, s.ipfsN))
	w.Key("traitTypes")
	w.Raw("[" + strings.Join(s.names[:len(s.traitTypes)], ",") + "]")
	w.Key("tiers")
	w.Raw("[" + strings.Join(s.names[len(s.traitTypes):], ",") + "]")
	w.EndObject()
	return w.String()
}

// nextUpload is the on-chain artwork AppendBytes expects next, -1 when all
// are complete. O(1): bytes arrive in artwork order (chainIdx, chainDone).
func (s *store) nextUpload() int64 {
	if s.chainDone >= s.onchainN {
		return -1
	}
	return getU32(s.chainIdx, int(s.chainDone)*4)
}

// ArtworkAt is the typed artwork record (a copy).
func ArtworkAt(storeID string, idx int64) media.Artwork {
	s := mustStore(storeID)
	return s.artwork(s.assertIdx(idx))
}

// ArtworkMeta is ArtworkAt without SHA256, Digest and CID (left ""): the
// cheap form for trait reads (a CID costs ~1.4M gas to encode in the VM).
func ArtworkMeta(storeID string, idx int64) media.Artwork {
	s := mustStore(storeID)
	return s.artworkMeta(s.assertIdx(idx))
}

func (s *store) assertIdx(idx int64) int64 {
	if idx < 0 || idx >= s.n {
		panic("no artwork " + strconv.FormatInt(idx, 10) + " in store " + s.idStr())
	}
	return idx
}

func (s *store) artwork(idx int64) media.Artwork {
	b, i := s.bucketOf(idx)
	r := decodeRecord(b.raw(i))
	a := s.meta(b, i, idx, &r)
	a.SHA256, a.Digest, a.CID = r.shaHex(), r.digestHex(), r.cid()
	return a
}

func (s *store) artworkMeta(idx int64) media.Artwork {
	b, i := s.bucketOf(idx)
	r := decodeRecord(b.raw(i))
	return s.meta(b, i, idx, &r)
}

func (s *store) meta(b *bucket, i int, idx int64, r *record) media.Artwork {
	a := media.Artwork{
		Index:    idx,
		Kind:     r.kind,
		Mime:     r.mime,
		Size:     r.size,
		Have:     r.have,
		Editions: r.editions,
		SlotEnd:  r.slotEnd,
		Title:    b.title(i),
		Tier:     s.tierName(r.tier),
		Traits:   make([]string, len(s.traitTypes)),
		Complete: r.complete(),
	}
	var js []string
	for k := range s.traitTypes {
		if id := r.traits[k]; id > 0 {
			e := s.dict[id-1]
			a.Traits[k] = e.v
			js = append(js, `{"trait_type":`+s.names[k]+`,"value":`+e.js+`}`)
		}
	}
	a.TraitsJSON = strings.Join(js, ",")
	if r.tier > 0 {
		a.TierJSON = s.names[len(s.traitTypes)+r.tier-1]
	}
	return a
}

// Artworks is one page of records as JSON (limit <= MaxPage = 20):
// [{index, kind, mime, mimeType, size, have, complete, editions, slotStart,
// slotEnd, sha256, digest, cid, title, tier, traits:[{trait_type,value}]}].
// kind is "chain" | "ipfs"; digest is the dag-pb root ("" otherwise); cid is
// "" for on-chain artworks. Built from parts escaped once at write time
// (type names, tiers, trait values) and joined once (UP-M1).
func Artworks(storeID string, offset, limit int64) string {
	s := mustStore(storeID)
	if limit <= 0 || limit > MaxPage {
		limit = MaxPage
	}
	if offset < 0 {
		offset = 0
	}
	parts := make([]string, 0, limit)
	for idx := offset; idx < s.n && idx < offset+limit; idx++ {
		parts = append(parts, s.artworkJSON(idx))
	}
	return "[" + strings.Join(parts, ",") + "]"
}

// ArtworkJSON is the JSON object of one artwork (also used by the
// upload engine's reads so both realms emit one shape).
func ArtworkJSON(storeID string, idx int64) string {
	s := mustStore(storeID)
	return s.artworkJSON(s.assertIdx(idx))
}

func (s *store) artworkJSON(idx int64) string {
	b, i := s.bucketOf(idx)
	r := decodeRecord(b.raw(i))
	tier := `""`
	if r.tier > 0 {
		tier = s.names[len(s.traitTypes)+r.tier-1]
	}
	traits := make([]string, 0, len(s.traitTypes))
	for k := range s.traitTypes {
		if id := r.traits[k]; id > 0 {
			traits = append(traits, `{"trait_type":`+s.names[k]+`,"value":`+s.dict[id-1].js+`}`)
		}
	}
	return `{"index":` + itoa(idx) +
		`,"kind":"` + media.KindName(r.kind) + `","mime":"` + media.MimeName(r.mime) + `","mimeType":"` + media.MimeType(r.mime) +
		`","size":` + itoa(r.size) + `,"have":` + itoa(r.have) + `,"complete":` + strconv.FormatBool(r.complete()) +
		`,"editions":` + itoa(r.editions) + `,"slotStart":` + itoa(r.slotEnd-r.editions) + `,"slotEnd":` + itoa(r.slotEnd) +
		`,"sha256":"` + r.shaHex() + `","digest":"` + r.digestHex() + `","cid":"` + r.cid() +
		`","title":` + jsonStr(b.title(i)) + `,"tier":` + tier + `,"traits":[` + strings.Join(traits, ",") + `]}`
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// ArtworkBytes is the raw file of a complete on-chain artwork, "" for an
// incomplete or IPFS one. Only complete files passed sha256 + CheckImage.
func ArtworkBytes(storeID string, idx int64) string {
	s := mustStore(storeID)
	b, i := s.bucketOf(s.assertIdx(idx))
	r := decodeRecord(b.raw(i))
	if r.kind != media.KindChain || !r.complete() {
		return ""
	}
	return s.readLog(r.logOff, r.size)
}

// ArtworkDataURI is "data:<mime>;base64,…" for a complete on-chain artwork,
// "" otherwise. mime is one of the four checked types (ENG-I3: no
// free-form media type ever reaches a data URI).
func ArtworkDataURI(storeID string, idx int64) string {
	s := mustStore(storeID)
	b, i := s.bucketOf(s.assertIdx(idx))
	r := decodeRecord(b.raw(i))
	if r.kind != media.KindChain || !r.complete() {
		return ""
	}
	return "data:" + media.MimeType(r.mime) + ";base64," +
		base64.StdEncoding.EncodeToString([]byte(s.readLog(r.logOff, r.size)))
}

// SlotArtwork maps a slot (0..slots-1) to its artwork index and 1-based
// edition: artwork i covers [slotEnd(i-1), slotEnd(i)). O(log n).
func SlotArtwork(storeID string, slot int64) (idx, edition int64) {
	s := mustStore(storeID)
	if slot < 0 || slot >= s.slots {
		panic("slot " + strconv.FormatInt(slot, 10) + " out of range 0.." + strconv.FormatInt(s.slots-1, 10))
	}
	if s.slots == s.n { // every artwork has one edition
		return slot, 1
	}
	var cached *bucket
	cachedKey := int64(-1)
	end := func(idx int64) int64 {
		if bk := idx / bucketSize; bk != cachedKey {
			cached, _ = s.bucketOf(idx)
			cachedKey = bk
		}
		return getU32(cached.raw(int(idx%bucketSize)), offSlotEnd)
	}
	lo, hi := int64(0), s.n-1
	for lo < hi {
		mid := (lo + hi) / 2
		if end(mid) > slot {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	b, i := s.bucketOf(lo)
	raw := b.raw(i)
	return lo, slot - (getU32(raw, offSlotEnd) - getU32(raw, offEditions)) + 1
}

// Composition is the set composition (design §8, D8 "drop table") as JSON:
// {store, sealed, artworks, slots,
//  tiers:[{name, artworks, slots}] (low -> high), untiered:{artworks, slots},
//  traits:[{trait_type, values:[{value, artworks, slots}], none:{artworks, slots}}]}.
// "slots" counts editions, i.e. the odds of a token: slots/total slots.
// O(tiers + distinct values): the counters are kept by AddArtworks /
// Truncate and the names are escaped once, so the largest store the limits
// allow stays far below the query gas cap (UP-M1).
func Composition(storeID string) string {
	s := mustStore(storeID)
	t := len(s.tiers)
	nt := len(s.traitTypes)
	tiers := make([]string, t)
	for i := 0; i < t; i++ {
		tiers[i] = `{"name":` + s.names[nt+i] + `,` + countPair(s.cnt[i+1], s.cnt[t+2+i]) + `}`
	}
	vals := make([][]string, nt)
	sumA := make([]int64, nt)
	sumS := make([]int64, nt)
	base := s.cntBase()
	for i, e := range s.dict {
		a, sl := s.cnt[base+2*i], s.cnt[base+2*i+1]
		sumA[e.k] += a
		sumS[e.k] += sl
		if a == 0 {
			continue // only used by truncated artworks
		}
		vals[e.k] = append(vals[e.k], `{"value":`+e.js+`,`+countPair(a, sl)+`}`)
	}
	traits := make([]string, nt)
	for k := 0; k < nt; k++ {
		traits[k] = `{"trait_type":` + s.names[k] + `,"values":[` + strings.Join(vals[k], ",") + `],"none":{` +
			countPair(s.n-sumA[k], s.slots-sumS[k]) + `}}`
	}
	return `{"store":"` + s.idStr() + `","sealed":` + strconv.FormatBool(s.sealed) + `,"artworks":` + itoa(s.n) +
		`,"slots":` + itoa(s.slots) + `,"tiers":[` + strings.Join(tiers, ",") + `],"untiered":{` +
		countPair(s.cnt[0], s.cnt[t+1]) + `},"traits":[` + strings.Join(traits, ",") + `]}`
}

// CountsJSON aggregates the real-name trait counts of a set of tokens, given
// each token's artwork index and edition (from SlotArtwork), as the members
// of a JSON object: "Tier":{tier:n}, then each creator trait type
// {value:n} in store order, "Edition":{"e/E":n} (artworks with E > 1) and
// "Storage":{"On-chain"|"IPFS":n}; types and values with no count are left
// out. Names are the JSON escaped once at write time, values in dictionary
// order (review UP-M1: no per-read escaping, integer counters only).
func CountsJSON(storeID string, idx, edition []int64) string {
	s := mustStore(storeID)
	if len(idx) != len(edition) {
		panic("CountsJSON: idx and edition differ in length")
	}
	t := len(s.tiers)
	nt := len(s.traitTypes)
	tierC := make([]int64, t+1)
	valC := make([]int64, len(s.dict))
	var onchain, ipfs int64
	edC := map[string]int64{}
	var edOrder []string
	recs := map[int64]record{}
	for i, x := range idx {
		r, ok := recs[x]
		if !ok {
			b, j := s.bucketOf(s.assertIdx(x))
			r = decodeRecord(b.raw(j))
			recs[x] = r
		}
		tierC[r.tier]++
		for k := 0; k < nt; k++ {
			if id := r.traits[k]; id > 0 {
				valC[id-1]++
			}
		}
		if r.kind == media.KindChain {
			onchain++
		} else {
			ipfs++
		}
		if r.editions > 1 {
			label := itoa(edition[i]) + "/" + itoa(r.editions)
			if _, seen := edC[label]; !seen {
				edOrder = append(edOrder, label)
			}
			edC[label]++
		}
	}
	var members []string
	var tiers []string
	for i := 1; i <= t; i++ {
		if tierC[i] > 0 {
			tiers = append(tiers, s.names[nt+i-1]+`:`+itoa(tierC[i]))
		}
	}
	if len(tiers) > 0 {
		members = append(members, `"Tier":{`+strings.Join(tiers, ",")+`}`)
	}
	vals := make([][]string, nt)
	for i, e := range s.dict {
		if valC[i] > 0 {
			vals[e.k] = append(vals[e.k], e.js+`:`+itoa(valC[i]))
		}
	}
	for k := 0; k < nt; k++ {
		if len(vals[k]) > 0 {
			members = append(members, s.names[k]+`:{`+strings.Join(vals[k], ",")+`}`)
		}
	}
	if len(edOrder) > 0 {
		eds := make([]string, len(edOrder))
		for i, l := range edOrder {
			eds[i] = `"` + l + `":` + itoa(edC[l])
		}
		members = append(members, `"Edition":{`+strings.Join(eds, ",")+`}`)
	}
	var st []string
	if onchain > 0 {
		st = append(st, `"On-chain":`+itoa(onchain))
	}
	if ipfs > 0 {
		st = append(st, `"IPFS":`+itoa(ipfs))
	}
	if len(st) > 0 {
		members = append(members, `"Storage":{`+strings.Join(st, ",")+`}`)
	}
	return strings.Join(members, ",")
}

func countPair(artworks, slots int64) string {
	return `"artworks":` + itoa(artworks) + `,"slots":` + itoa(slots)
}

// TierSlots is the typed tier part of Composition: tier names (low ->
// high), the slots each holds, and the slots of untiered artworks. O(tiers).
func TierSlots(storeID string) (tiers []string, slots []int64, untiered int64) {
	s := mustStore(storeID)
	t := len(s.tiers)
	return append([]string{}, s.tiers...), append([]int64{}, s.cnt[t+2:2*t+2]...), s.cnt[t+1]
}

// Render stays minimal and prints no creator text; uploaded collections
// are browsed in the gallery realm.
func Render(path string) string {
	out := "# Sinopia asset stores\n\n" + strconv.FormatInt(storeCount, 10) +
		" stores. Sealed stores never change; uploaded collections are browsed in the Sinopia gallery.\n"
	if strings.HasPrefix(path, "s/") {
		id := strings.TrimPrefix(path, "s/")
		if n, err := strconv.ParseInt(id, 10, 64); err == nil && n >= 1 && n <= storeCount {
			s := mustStore(strconv.FormatInt(n, 10))
			state := "draft"
			if s.sealed {
				state = "sealed at height " + strconv.FormatInt(s.sealedHeight, 10)
			}
			out += "\n## Store " + s.idStr() + "\n\n- State: " + state +
				"\n- Artworks: " + strconv.FormatInt(s.n, 10) + " (" + strconv.FormatInt(s.onchainN, 10) +
				" on-chain, " + strconv.FormatInt(s.ipfsN, 10) + " IPFS)\n- Slots: " + strconv.FormatInt(s.slots, 10) +
				"\n- On-chain bytes: " + strconv.FormatInt(s.onchainBytes, 10) + "\n- Storage: " +
				media.Badge(s.onchainN, s.ipfsN) + "\n"
		}
	}
	return out
}

package assets

import (
	"encoding/hex"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
)

// Fixed artwork record, recBytes long, bucketSize records per avl value
// (design §4; one key per 64 artworks instead of one per artwork):
//
//	off  0  kind u8          (media.Kind*)
//	     1  mime u8          (media.Mime*)
//	     2  size u32         declared byte size
//	     6  have u32         bytes received (= size when complete; ipfs: = size at add)
//	    10  editions u32
//	    14  slotEnd u32      prefix sum of editions, exclusive
//	    18  logOff u32       chain: offset in the byte log (= declared on-chain bytes before it)
//	    22  tier u8          0 = none, else 1-based index into tiers
//	    23  traits [8]u8     per trait type: dictionary index + 1, 0 = none (MaxTraitTypes)
//	    31  sha256 [32]      of the file bytes
//	    63  digest [32]      dag-pb root digest (UnixFS), zero otherwise
//
// All fields are big-endian. A raw CID is derived from sha256.
const (
	recBytes   = 95
	bucketSize = 64

	offKind     = 0
	offMime     = 1
	offSize     = 2
	offHave     = 6
	offEditions = 10
	offSlotEnd  = 14
	offLogOff   = 18
	offTier     = 22
	offTraits   = 23
	offSHA      = offTraits + MaxTraitTypes // 31
	offDigest   = offSHA + 32             // 63
)

type record struct {
	kind, mime                            int
	size, have, editions, slotEnd, logOff int64
	tier                                  int
	traits                                [MaxTraitTypes]int
	sha, digest                           string // 32 raw bytes each
}

func putU32(b []byte, off int, v int64) {
	if v < 0 || v > 0xFFFFFFFF {
		panic("assets: value out of uint32 range")
	}
	b[off], b[off+1], b[off+2], b[off+3] = byte(v>>24), byte(v>>16), byte(v>>8), byte(v)
}

func getU32(s string, off int) int64 {
	return int64(s[off])<<24 | int64(s[off+1])<<16 | int64(s[off+2])<<8 | int64(s[off+3])
}

func (r *record) encode() string {
	b := make([]byte, recBytes)
	b[offKind] = byte(r.kind)
	b[offMime] = byte(r.mime)
	putU32(b, offSize, r.size)
	putU32(b, offHave, r.have)
	putU32(b, offEditions, r.editions)
	putU32(b, offSlotEnd, r.slotEnd)
	putU32(b, offLogOff, r.logOff)
	b[offTier] = byte(r.tier)
	for i := 0; i < MaxTraitTypes; i++ {
		b[offTraits+i] = byte(r.traits[i])
	}
	copy(b[offSHA:offSHA+32], []byte(r.sha))
	copy(b[offDigest:offDigest+32], []byte(r.digest))
	return string(b)
}

func decodeRecord(s string) record {
	r := record{
		kind:     int(s[offKind]),
		mime:     int(s[offMime]),
		size:     getU32(s, offSize),
		have:     getU32(s, offHave),
		editions: getU32(s, offEditions),
		slotEnd:  getU32(s, offSlotEnd),
		logOff:   getU32(s, offLogOff),
		tier:     int(s[offTier]),
		sha:      s[offSHA : offSHA+32],
		digest:   s[offDigest : offDigest+32],
	}
	for i := 0; i < MaxTraitTypes; i++ {
		r.traits[i] = int(s[offTraits+i])
	}
	return r
}

func (r *record) complete() bool { return r.have == r.size }

func (r *record) shaHex() string { return hex.EncodeToString([]byte(r.sha)) }

func (r *record) cid() string {
	switch r.kind {
	case media.KindIPFSRaw:
		return media.CIDFromDigest(media.CodecRaw, r.shaHex())
	case media.KindIPFSUnixFS:
		return media.CIDFromDigest(media.CodecDagPB, hex.EncodeToString([]byte(r.digest)))
	}
	return ""
}

func (r *record) digestHex() string {
	if r.kind != media.KindIPFSUnixFS {
		return ""
	}
	return hex.EncodeToString([]byte(r.digest))
}

// bucket holds up to bucketSize packed records and their titles
// (concatenated, each prefixed by its byte length as one byte).
type bucket struct {
	rec    string
	titles string
}

func (b *bucket) count() int { return len(b.rec) / recBytes }

func (b *bucket) raw(i int) string { return b.rec[i*recBytes : (i+1)*recBytes] }

func (b *bucket) setRaw(i int, enc string) {
	b.rec = b.rec[:i*recBytes] + enc + b.rec[(i+1)*recBytes:]
}

func (b *bucket) title(i int) string {
	off := 0
	for k := 0; k < i; k++ {
		off += 1 + int(b.titles[off])
	}
	n := int(b.titles[off])
	return b.titles[off+1 : off+1+n]
}

// keep trims the bucket to its first n records and titles.
func (b *bucket) keep(n int) {
	off := 0
	for k := 0; k < n; k++ {
		off += 1 + int(b.titles[off])
	}
	b.rec = b.rec[:n*recBytes]
	b.titles = b.titles[:off]
}

package upload

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	assets "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/assets/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"
)

// Every function in this file is read-only. Every token read returns core's
// placeholder / "Unrevealed" before the collection is Final (T5).

// Readiness reasons (Status.reason).
const (
	ReasonNotUpload      = "not-upload"
	ReasonNoStore        = "no-store"
	ReasonNotSealed      = "store-not-sealed"
	ReasonBoundElsewhere = "bound-elsewhere"
	ReasonSupply         = "supply-mismatch"
	ReasonUnbound        = "unbound"
	ReasonReady          = "ready"
)

type col struct {
	cid     string
	info    types.CollectionInfo
	upload  bool
	store   string // params store id ("" if none or unknown)
	si      media.StoreInfo
	b       *binding // this collection's binding (nil if unbound)
	boundTo string   // collection the store is bound to ("" if none)
}

func loadCol(cid string) col {
	c := col{cid: cid, info: core.Info(cid)}
	c.upload = c.info.EngineID == selfPath
	if !c.upload {
		return c
	}
	if id, ok := parseParams(c.info.Params); ok && storeExists(id) {
		c.store = id
		c.si = assets.Info(id)
		if v := bound.Get(id); v != nil {
			c.boundTo = v.(string)
		}
	}
	if v := byCID.Get(cid); v != nil {
		c.b = v.(*binding)
	}
	return c
}

// status: ready = bound ∧ store sealed ∧ supply match (§6).
func (c *col) status() (bool, string) {
	switch {
	case !c.upload:
		return false, ReasonNotUpload
	case c.store == "":
		return false, ReasonNoStore
	case !c.si.Sealed:
		return false, ReasonNotSealed
	case c.boundTo != "" && c.boundTo != c.cid:
		return false, ReasonBoundElsewhere
	case c.info.MaxSupply != c.si.Slots:
		return false, ReasonSupply
	case c.b == nil || c.b.store != c.store:
		return false, ReasonUnbound
	}
	return true, ReasonReady
}

func (c *col) badge() string {
	if !c.upload {
		return "computed"
	}
	if ok, _ := c.status(); !ok {
		return "unbound"
	}
	return media.Badge(c.si.OnchainN, c.si.IPFSN)
}

func mustUpload(cid string) col {
	c := loadCol(cid)
	if !c.upload {
		panic("collection " + cid + " does not use the upload engine")
	}
	return c
}

// IsUpload reports whether cid's engine is this adapter.
func IsUpload(cid string) bool { return core.Info(cid).EngineID == selfPath }

// StoreOf is the store named by cid's params ("" if none).
func StoreOf(cid string) string { return loadCol(cid).store }

// Readiness is the typed Status for other realms.
func Readiness(cid string) (ready bool, reason, store, badge string) {
	c := loadCol(cid)
	ready, reason = c.status()
	return ready, reason, c.store, c.badge()
}

// Status is {cid, upload, state, store, bound, ready, reason, badge, settled,
// maxSupply, slots}. The frontend shows the mint UI only when ready (T14).
func Status(cid string) string {
	c := loadCol(cid)
	ready, reason := c.status()
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("cid", cid)
	w.BoolField("upload", c.upload)
	w.StrField("state", c.info.State.String())
	w.StrField("store", c.store)
	w.BoolField("bound", c.b != nil)
	w.BoolField("ready", ready)
	w.StrField("reason", reason)
	w.StrField("badge", c.badge())
	w.BoolField("settled", c.b != nil && c.b.key != "")
	w.IntField("maxSupply", c.info.MaxSupply)
	w.IntField("slots", c.si.Slots)
	w.EndObject()
	return w.String()
}

// StorageBadge is "computed" (any other engine), "onchain", "ipfs",
// "mixed", or "unbound" for an upload collection that is not ready (§9).
func StorageBadge(cid string) string {
	c := loadCol(cid)
	return c.badge()
}

// SetComposition is {collection, store, ready, reason, set}, set =
// assets.Composition of the collection's store: slots per tier and per
// trait value over the planned set (public and fixed before the sale, D8).
func SetComposition(cid string) string {
	c := mustUpload(cid)
	if c.store == "" {
		panic("collection " + cid + " names no store")
	}
	ready, reason := c.status()
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("collection", cid)
	w.StrField("store", c.store)
	w.BoolField("ready", ready)
	w.StrField("reason", reason)
	w.Key("set")
	w.Raw(assets.Composition(c.store))
	w.EndObject()
	return w.String()
}

const (
	stHidden   = 0 // not Final: placeholder
	stNotReady = 1 // Final but not bound/ready: no art
	stResolved = 2
)

func readToken(cid, tid string) (col, resolved, int, error) {
	c := mustUpload(cid)
	if _, err := core.OwnerOf(cid, tid); err != nil {
		return c, resolved{}, stHidden, err
	}
	if c.info.State != types.StateFinal {
		return c, resolved{}, stHidden, nil
	}
	if ok, _ := c.status(); !ok {
		return c, resolved{}, stNotReady, nil
	}
	salt := saltOf(cid, c.b)
	if salt == "" {
		return c, resolved{}, stNotReady, nil
	}
	n := tidNum(tid)
	r := assign(cid, tid, n, c.info, c.store, c.si, keyOf(cid, c.b, salt), nil)
	return c, r, stResolved, nil
}

func mustReadToken(cid, tid string) (col, resolved, int) {
	c, r, st, err := readToken(cid, tid)
	if err != nil {
		panic(err)
	}
	return c, r, st
}

// TokenURI is the canonical art URI: "data:<mime>;base64,…" for on-chain
// art, "ipfs://<cidv1>" for IPFS art; core's placeholder before Final and
// core's TokenURI (the generic card) for a collection that is not ready.
func TokenURI(cid, tid string) (string, error) {
	if !IsUpload(cid) {
		return "", errors.New("collection " + cid + " does not use the upload engine")
	}
	_, r, st, err := readToken(cid, tid)
	if err != nil {
		return "", err
	}
	if st != stResolved {
		return core.TokenURI(cid, tid)
	}
	return artURI(r), nil
}

func artURI(r resolved) string {
	if r.art.Kind == media.KindChain {
		return assets.ArtworkDataURI(r.store, r.art.Index)
	}
	return "ipfs://" + r.art.CID
}

// TokenImage is the inline image: a data URI for on-chain art, "" for IPFS
// art (never a remote URL); core's placeholder before Final.
func TokenImage(cid, tid string) string {
	_, r, st := mustReadToken(cid, tid)
	if st != stResolved {
		uri, _ := core.TokenURI(cid, tid)
		return uri
	}
	if r.art.Kind != media.KindChain {
		return ""
	}
	return assets.ArtworkDataURI(r.store, r.art.Index)
}

// Assignment is the typed TokenArtwork for other realms (gallery): ready is
// false before Final or when the collection is not ready; a is a copy.
func Assignment(cid, tid string) (ready bool, slot, edition int64, a media.Artwork) {
	_, r, st := mustReadToken(cid, tid)
	if st != stResolved {
		return false, 0, 0, media.Artwork{}
	}
	return true, r.slot, r.edition, r.art
}

// TokenArtwork is the token's assignment as JSON:
// {collection, tid, revealed, ready, reason} and, once revealed and ready,
// {store, artwork, slot, edition, editions, assignment, kind, mime, mimeType,
// size, sha256, digest, cid, uri, tier, tierSource, title, traits}.
// uri is "ipfs://<cid>" for IPFS art and "" for on-chain art (read its bytes
// with TokenImage / TokenURI: base64 of up to 256 KiB is not free).
func TokenArtwork(cid, tid string) string {
	c, r, st := mustReadToken(cid, tid)
	_, reason := c.status()
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("collection", cid)
	w.StrField("tid", tid)
	w.BoolField("revealed", c.info.State == types.StateFinal)
	w.BoolField("ready", st == stResolved)
	w.StrField("reason", reason)
	if st == stResolved {
		a := r.art
		w.StrField("store", r.store)
		w.IntField("artwork", a.Index)
		w.IntField("slot", r.slot)
		w.IntField("edition", r.edition)
		w.IntField("editions", a.Editions)
		w.StrField("assignment", assignmentMode(r.si))
		w.StrField("kind", media.KindName(a.Kind))
		w.StrField("mime", media.MimeName(a.Mime))
		w.StrField("mimeType", media.MimeType(a.Mime))
		w.IntField("size", a.Size)
		w.StrField("sha256", a.SHA256)
		w.StrField("digest", a.Digest)
		w.StrField("cid", a.CID)
		if a.Kind == media.KindChain {
			w.StrField("uri", "")
		} else {
			w.StrField("uri", "ipfs://"+a.CID)
		}
		w.StrField("tier", a.Tier)
		w.StrField("tierSource", "creator")
		w.StrField("title", a.Title)
		w.Key("traits")
		w.Raw(realTraitsJSON(r))
	}
	w.EndObject()
	return w.String()
}

func assignmentMode(si media.StoreInfo) string {
	if si.Artworks == 1 {
		return "edition"
	}
	return "shuffled"
}

// realTraits are the upload-path attributes with the creator's real type
// names: Tier, the creator's traits in store order, Edition (when the
// artwork has more than one) and Storage.
func realTraits(r resolved) []engine.Trait {
	a := r.art
	out := []engine.Trait{}
	if a.Tier != "" {
		out = append(out, engine.Trait{Type: "Tier", Value: a.Tier})
	}
	for k, v := range a.Traits {
		if v != "" {
			out = append(out, engine.Trait{Type: r.si.TraitTypes[k], Value: v})
		}
	}
	if a.Editions > 1 {
		out = append(out, engine.Trait{Type: "Edition", Value: editionLabel(r.edition, a.Editions)})
	}
	out = append(out, engine.Trait{Type: "Storage", Value: storageLabel(a.Kind)})
	return out
}

var (
	unrevealed = []engine.Trait{{Type: "Status", Value: "Unrevealed"}}
	notReady   = []engine.Trait{{Type: "Status", Value: "Not ready"}}
)

const (
	unrevealedJSON = `[{"trait_type":"Status","value":"Unrevealed"}]`
	notReadyJSON   = `[{"trait_type":"Status","value":"Not ready"}]`
)

// realTraitsJSON is realTraits as JSON, from the names the store escaped
// once (media.Artwork.TierJSON / TraitsJSON): same bytes as writeTraits of
// realTraits, without escaping creator text on every read (review UP-M1).
func realTraitsJSON(r resolved) string {
	a := r.art
	parts := make([]string, 0, 4)
	if a.TierJSON != "" {
		parts = append(parts, `{"trait_type":"Tier","value":`+a.TierJSON+`}`)
	}
	if a.TraitsJSON != "" {
		parts = append(parts, a.TraitsJSON)
	}
	if a.Editions > 1 {
		parts = append(parts, `{"trait_type":"Edition","value":"`+editionLabel(r.edition, a.Editions)+`"}`)
	}
	parts = append(parts, `{"trait_type":"Storage","value":"`+storageLabel(a.Kind)+`"}`)
	return "[" + strings.Join(parts, ",") + "]"
}

func writeTraits(w *safe.JSONWriter, ts []engine.Trait) {
	w.BeginArray()
	for _, t := range ts {
		w.BeginObject()
		w.StrField("trait_type", t.Type)
		w.StrField("value", t.Value)
		w.EndObject()
	}
	w.EndArray()
}

// TokenTraitList is the typed real-name trait list of one token (a copy).
func TokenTraitList(cid, tid string) []engine.Trait {
	_, r, st := mustReadToken(cid, tid)
	switch st {
	case stHidden:
		return append([]engine.Trait{}, unrevealed...)
	case stNotReady:
		return append([]engine.Trait{}, notReady...)
	}
	return realTraits(r)
}

// TokenTraits is TokenTraitList as [{"trait_type","value"}] JSON.
func TokenTraits(cid, tid string) string {
	_, r, st := mustReadToken(cid, tid)
	switch st {
	case stHidden:
		return unrevealedJSON
	case stNotReady:
		return notReadyJSON
	}
	return realTraitsJSON(r)
}

// TokenMetadata is the canonical metadata (§10.2). Before Final: core's
// placeholder image and [{Status: Unrevealed}].
func TokenMetadata(cid, tid string) string {
	c, r, st := mustReadToken(cid, tid)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("name", c.info.Name+" #"+tid)
	w.StrField("description", c.info.Description)
	if st != stResolved {
		uri, _ := core.TokenURI(cid, tid)
		w.StrField("image", uri)
		w.Key("attributes")
		if st == stHidden {
			writeTraits(w, unrevealed)
		} else {
			writeTraits(w, notReady)
		}
		w.EndObject()
		return w.String()
	}
	a := r.art
	w.StrField("image", artURI(r))
	w.StrField("image_mime", media.MimeType(a.Mime))
	w.StrField("image_sha256", a.SHA256)
	w.IntField("image_size", a.Size)
	w.Key("attributes")
	w.Raw(realTraitsJSON(r))
	w.Key("properties")
	w.BeginObject()
	w.StrField("collection", cid)
	w.StrField("store", r.store)
	w.IntField("artwork", a.Index)
	w.StrField("edition", editionLabel(r.edition, a.Editions))
	if a.Kind == media.KindChain {
		w.StrField("storage", "onchain")
	} else {
		w.StrField("storage", "ipfs")
		w.StrField("cid", a.CID)
	}
	w.StrField("title", a.Title)
	w.StrField("tier", a.Tier)
	w.StrField("tierSource", "creator")
	w.StrField("assignment", assignmentMode(r.si))
	w.BoolField("fair", core.FairLaunch(cid))
	w.EndObject()
	w.EndObject()
	return w.String()
}

// TraitLists returns, for tokens offset+1 … offset+limit (limit <=
// MaxTraitLists, burned tokens skipped), the token ids and their real-name
// traits. The permutation key is computed once per call.
func TraitLists(cid string, offset, limit int64) ([]string, [][]engine.Trait) {
	tids, rs, st := tokenPage(cid, offset, limit, MaxTraitLists)
	lists := make([][]engine.Trait, len(tids))
	for i := range tids {
		switch st {
		case stHidden:
			lists[i] = append([]engine.Trait{}, unrevealed...)
		case stNotReady:
			lists[i] = append([]engine.Trait{}, notReady...)
		default:
			lists[i] = realTraits(rs[i])
		}
	}
	return tids, lists
}

// TraitJSONLists is TraitLists with each token's traits as a JSON array
// (the bytes TokenTraits returns), for pages that print them (reader.Cards).
// limit <= MaxTraitJSONLists.
func TraitJSONLists(cid string, offset, limit int64) ([]string, []string) {
	tids, rs, st := tokenPage(cid, offset, limit, MaxTraitJSONLists)
	out := make([]string, len(tids))
	for i := range tids {
		switch st {
		case stHidden:
			out[i] = unrevealedJSON
		case stNotReady:
			out[i] = notReadyJSON
		default:
			out[i] = realTraitsJSON(rs[i])
		}
	}
	return tids, out
}

// tokenPage resolves tokens offset+1 … offset+limit (limit <= max, burned
// skipped) with one permutation key per call and one record read per
// distinct artwork. st is stHidden before Final, stNotReady when the
// collection is Final but not ready, else stResolved.
func tokenPage(cid string, offset, limit, max int64) ([]string, []resolved, int) {
	c := mustUpload(cid)
	if limit <= 0 || limit > max {
		limit = max
	}
	if offset < 0 {
		offset = 0
	}
	st := stHidden
	key := ""
	if c.info.State == types.StateFinal {
		st = stNotReady
		if ready, _ := c.status(); ready {
			if salt := saltOf(cid, c.b); salt != "" {
				key = keyOf(cid, c.b, salt)
				st = stResolved
			}
		}
	}
	cache := map[int64]media.Artwork{}
	var tids []string
	var rs []resolved
	for n := offset + 1; n <= c.info.Minted && n <= offset+limit; n++ {
		tid := strconv.FormatInt(n, 10)
		if _, err := core.OwnerOf(cid, tid); err != nil {
			continue // burned
		}
		tids = append(tids, tid)
		if st == stResolved {
			rs = append(rs, assign(cid, tid, n, c.info, c.store, c.si, key, cache))
		}
	}
	return tids, rs, st
}

// TraitCounts is {"n": tokens counted, "counts": {type: {value: count}}}
// over tokens offset+1 … offset+limit (limit <= MaxTraitCounts, burned
// skipped), with the creator's real names: Tier, the creator's trait types
// (store order, values in dictionary order), Edition, Storage. Before Final
// every token counts as {"Status": "Unrevealed"}, Final but not ready as
// {"Status": "Not ready"}. One permutation key per call; the counting runs in
// assets/v1 over integer ids (review UP-M1).
func TraitCounts(cid string, offset, limit int64) string {
	c := mustUpload(cid)
	if limit <= 0 || limit > MaxTraitCounts {
		limit = MaxTraitCounts
	}
	if offset < 0 {
		offset = 0
	}
	st := stHidden
	key := ""
	if c.info.State == types.StateFinal {
		st = stNotReady
		if ready, _ := c.status(); ready {
			if salt := saltOf(cid, c.b); salt != "" {
				key = keyOf(cid, c.b, salt)
				st = stResolved
			}
		}
	}
	var n int64
	var idxs, eds []int64
	for t := offset + 1; t <= c.info.Minted && t <= offset+limit; t++ {
		if _, err := core.OwnerOf(cid, strconv.FormatInt(t, 10)); err != nil {
			continue // burned
		}
		n++
		if st == stResolved {
			idx, ed := assets.SlotArtwork(c.store, media.Slot(key, c.si.Artworks, c.si.Slots, t))
			idxs = append(idxs, idx)
			eds = append(eds, ed)
		}
	}
	head := `{"n":` + strconv.FormatInt(n, 10) + `,"counts":{`
	switch {
	case n == 0:
		return head + `}}`
	case st == stHidden:
		return head + `"Status":{"Unrevealed":` + strconv.FormatInt(n, 10) + `}}}`
	case st == stNotReady:
		return head + `"Status":{"Not ready":` + strconv.FormatInt(n, 10) + `}}}`
	}
	return head + assets.CountsJSON(c.store, idxs, eds) + `}}`
}

// TraitsBatch is [{tid, traits:[{trait_type, value}]}] for tokens
// offset+1 … offset+limit (limit <= MaxTraitsBatch), burned tokens skipped.
func TraitsBatch(cid string, offset, limit int64) string {
	tids, lists := traitJSONPage(cid, offset, limit, MaxTraitsBatch)
	parts := make([]string, len(tids))
	for i, tid := range tids {
		parts[i] = `{"tid":"` + tid + `","traits":` + lists[i] + `}`
	}
	return "[" + strings.Join(parts, ",") + "]"
}

func traitJSONPage(cid string, offset, limit, max int64) ([]string, []string) {
	if limit <= 0 || limit > max {
		limit = max
	}
	return TraitJSONLists(cid, offset, limit)
}

// Render stays minimal; uploaded collections are browsed in the gallery.
func Render(path string) string {
	return "# Sinopia Upload engine\n\n" + strconv.Itoa(byCID.Size()) +
		" collections bound to sealed asset stores. Each token shows the artwork of its slot, assigned by a " +
		"permutation keyed by the collection's final salt; tiers and traits are assigned by the creator.\n"
}

package upload

import (
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
)

// cardSVG is the generic card: the registration sample (unique
// fingerprint, CV-L3), RenderWith output, and the answer to any call that
// is not core's real render of a revealed, bound token.
const cardSVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">` +
	`<rect width="512" height="512" fill="#16130f"/>` +
	`<rect x="20" y="20" width="472" height="472" fill="none" stroke="#b5332e" stroke-width="3"/>` +
	`<text x="256" y="240" fill="#eeeeee" font-family="monospace" font-size="30" text-anchor="middle">Sinopia Upload</text>` +
	`<text x="256" y="282" fill="#999999" font-family="monospace" font-size="15" text-anchor="middle">art from a sealed asset store</text>` +
	`</svg>`

// certificateSVG stands in for raster and IPFS art on core's TokenURI
// path, which only carries allowlisted SVG (§10.1). Every text is
// XML-escaped; the document stays far below MaxSVGBytes.
func certificateSVG(r resolved) string {
	a := r.art
	title := a.Title
	if title == "" {
		title = "Artwork #" + strconv.FormatInt(a.Index+1, 10)
	}
	tier := "no tier"
	if a.Tier != "" {
		tier = a.Tier + " — creator tier"
	}
	where := strings.ToUpper(media.MimeName(a.Mime)) + " · " + sizeLabel(a.Size) + " · stored on-chain"
	if a.Kind != media.KindChain {
		where = "IPFS · " + strings.ToUpper(media.MimeName(a.Mime)) + " · " + sizeLabel(a.Size)
	}
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">`)
	b.WriteString(`<rect width="512" height="512" fill="#16130f"/>`)
	b.WriteString(`<rect x="16" y="16" width="480" height="480" fill="none" stroke="#b5332e" stroke-width="2"/>`)
	line := func(y int, size int, fill, text string) {
		b.WriteString(`<text x="256" y="` + strconv.Itoa(y) + `" fill="` + fill + `" font-family="monospace" font-size="` +
			strconv.Itoa(size) + `" text-anchor="middle">` + safe.XMLEscape(text) + `</text>`)
	}
	line(78, 24, "#eeeeee", r.info.Name)
	line(116, 20, "#cccccc", "#"+r.tid)
	line(196, 20, "#eeeeee", title)
	line(232, 16, "#d9a441", tier)
	if a.Editions > 1 {
		line(262, 14, "#aaaaaa", "edition "+editionLabel(r.edition, a.Editions))
	}
	line(316, 14, "#aaaaaa", where)
	if a.CID != "" {
		line(340, 11, "#888888", a.CID)
	}
	line(364, 12, "#888888", "sha256 "+a.SHA256[:16]+"…")
	line(452, 11, "#777777", "full image: "+selfPath+" TokenURI")
	b.WriteString(`</svg>`)
	return b.String()
}

func sizeLabel(n int64) string {
	if n < 1024 {
		return strconv.FormatInt(n, 10) + " B"
	}
	tenths := (n*10 + 512) / 1024
	return strconv.FormatInt(tenths/10, 10) + "." + strconv.FormatInt(tenths%10, 10) + " KB"
}

// Package upload is the engine/v1 adapter for uploaded collections
// (docs/uploaded-collections.md §5.3, §7–§10, §0a). Core knows it as one
// more engine; each collection's params name one sealed asset store
// ("store:<id>", r/…/assets/v1) and Bind locks that store to the collection
// while it is a Draft. After the reveal every token shows the artwork of the
// slot a salt-keyed permutation gives it.
//
// What holds, and why:
//   - art theft (T1): ValidateParams accepts a store only when its owner
//     signs the Create tx; Bind needs caller == collection creator == store
//     owner, from a wallet;
//   - no swap after sale (T2): stores are sealed before Bind and never
//     change; params are fixed by core; Bind and Unbind run only while core
//     says Draft, i.e. before any token was ever minted;
//   - one collection per store (T3); slots == maxSupply (T13);
//   - snipe resistance (T4/T5): before Final core shows its placeholder and
//     never calls Render/Traits; every read here checks Final too; the
//     assignment needs the final salt; Render answers core's real call only
//     (CollectionID, params and seed must match core's), so RenderWith
//     (CollectionID "0") always gets the generic card;
//   - SA-L5: this realm and assets/v1 may not be payees (Bind refuses);
//   - I-12: Render, Traits and ValidateParams only read; Bind, Unbind and
//     Settle are crossing functions; there is no exported non-crossing
//     mutator.
//
// The adapter is stateful by design (bindings and cached keys), declares
// Living false, takes no fee (D3) and holds no coins.
package upload

import (
	"chain"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	assets "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/assets/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"
)

// author claims the engine in core (ClaimEngine).
// TODO(mainnet): the platform's engine-author key, not the deployer.
var author = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")

func Author() address { return author }

// FeeBps is the engine-author fee (D3: none; fixed forever at Register).
const FeeBps = 0

// Core-path trait slots (engine/v1 manifests fix their trait types at
// registration, so creator trait types appear as "Trait k" = "<Type>: <Value>").
const (
	TraitTier    = "Creator tier"
	TraitArtwork = "Artwork"
	TraitEdition = "Edition"
	TraitStorage = "Storage"
	TraitSlots   = assets.MaxTraitTypes
)

// MaxTraitsBatch bounds TraitsBatch (JSON); MaxTraitLists bounds the typed
// TraitLists the reader pages rarity counts with. Both compute the
// permutation key once per call (§0a), never per token.
// Sized so the worst store the asset limits allow stays <= 1B test gas per
// call (review UP-M1; r/reader/zz_worst_gas_test.gno).
const (
	MaxTraitsBatch    = 20  // JSON (was 50)
	MaxTraitJSONLists = 20  // typed, JSON per token (reader.Cards)
	MaxTraitLists     = 250 // typed (was 500)
	MaxTraitCounts    = 200 // TraitCounts (reader.TraitCounts)
)

var (
	selfPath   string
	assetsPath string

	bound avl.Tree // store id -> cid
	byCID avl.Tree // cid -> *binding
)

type binding struct {
	store string
	salt  string // cached by Settle ("" = read core.Provenance)
	key   string // media.PermKey(cid, salt), cached by Settle
}

func init(cur realm) {
	selfPath = cur.PkgPath()
	assetsPath = strings.TrimSuffix(selfPath, "/engines/upload") + "/assets/v1"
}

// SelfPath and AssetsPath are the engine id and the store realm it reads.
func SelfPath() string   { return selfPath }
func AssetsPath() string { return assetsPath }

// --- engine/v1 ---------------------------------------------------------------

// impl is zero-size and declared here, so core runs it with this realm's
// authority (interrealm v2 borrow rule #1).
type impl struct{}

func traitTypes() []string {
	out := []string{TraitTier, TraitArtwork, TraitEdition, TraitStorage}
	for k := 1; k <= TraitSlots; k++ {
		out = append(out, "Trait "+strconv.Itoa(k))
	}
	return out
}

func (impl) Manifest() engine.Manifest {
	return engine.Manifest{
		Name:    "Sinopia Upload",
		Version: "1.0.0",
		Description: "Uploaded art: each token shows the artwork of its slot in a sealed asset store (assets/v1), " +
			"assigned by a permutation keyed by the final salt. Stateful platform engine (store bindings); " +
			"tiers and traits are assigned by the creator.",
		License:     "artist's own",
		Author:      author,
		TraitTypes:  traitTypes(),
		Living:      false,
		MaxSVGBytes: media.MaxSVGBytes,
		FeeBps:      FeeBps,
	}
}

// ValidateParams accepts "" (registration, Studio) or exactly
// "store:<id>" of an existing, sealed, unbound store whose owner signs this
// transaction (art-theft guard). In qeval there is no signer, so store
// params are refused there: intended (Studio never offers them). No writes.
func (impl) ValidateParams(p string) error {
	if p == "" {
		return nil
	}
	id, ok := parseParams(p)
	if !ok {
		return errors.New("params must be store:<id>")
	}
	if !storeExists(id) {
		return errors.New("unknown store " + id)
	}
	si := assets.Info(id)
	if !si.Sealed {
		return errors.New("store " + id + " is not sealed")
	}
	if v := bound.Get(id); v != nil {
		return errors.New("store " + id + " is already bound to collection " + v.(string))
	}
	if si.Owner != unsafe.OriginCaller() {
		return errors.New("store owner is not the signer")
	}
	return nil
}

func (impl) Render(in engine.Input) string {
	r, ok := coreResolve(in)
	if !ok {
		return cardSVG
	}
	if r.art.Kind == media.KindChain && r.art.Mime == media.MimeSVG {
		return assets.ArtworkBytes(r.store, r.art.Index) // passed AssertSVG(16 KiB) at upload; core re-checks
	}
	return certificateSVG(r)
}

func (impl) Traits(in engine.Input) []engine.Trait {
	if in.Params == "" || in.CollectionID == "0" {
		return []engine.Trait{}
	}
	r, ok := coreResolve(in)
	if !ok {
		return []engine.Trait{{Type: TraitStorage, Value: "Not bound"}}
	}
	a := r.art
	var out []engine.Trait
	if a.Tier != "" {
		out = append(out, engine.Trait{Type: TraitTier, Value: a.Tier})
	}
	title := a.Title
	if title == "" {
		title = "#" + strconv.FormatInt(a.Index+1, 10)
	}
	out = append(out, engine.Trait{Type: TraitArtwork, Value: title})
	if a.Editions > 1 {
		out = append(out, engine.Trait{Type: TraitEdition, Value: editionLabel(r.edition, a.Editions)})
	}
	out = append(out, engine.Trait{Type: TraitStorage, Value: storageLabel(a.Kind)})
	for k, v := range a.Traits {
		if v != "" {
			out = append(out, engine.Trait{Type: "Trait " + strconv.Itoa(k+1), Value: r.si.TraitTypes[k] + ": " + v})
		}
	}
	return out
}

// Register is an explicit call (not init: under the inert package policy
// init runs in the approver's tx). Anyone may call it, once.
func Register(cur realm) string {
	return core.RegisterEngine(cross(cur), impl{})
}

// --- binding -----------------------------------------------------------------

// Bind locks the collection's store (its params "store:<id>") to the
// collection. Caller == core creator == store owner, from a wallet; core
// state Draft; the collection uses this engine; the store is sealed and not
// bound elsewhere; maxSupply == the store's slots; no primary or royalty
// payee is this realm or assets/v1 (SA-L5). Event StoreBound{store, cid}.
func Bind(cur realm, cid string) {
	assertWallet(cur)
	who := cur.Previous().Address()
	info := core.Info(cid)
	assertUploadDraft(info, cid)
	if who != info.Creator {
		panic("only the collection's creator can bind its store")
	}
	id, ok := parseParams(info.Params)
	if !ok || !storeExists(id) {
		panic("collection " + cid + " has no store params (store:<id>)")
	}
	si := assets.Info(id)
	if si.Owner != who {
		panic("only the owner of store " + id + " can bind it")
	}
	if !si.Sealed {
		panic("store " + id + " is not sealed")
	}
	if byCID.Has(cid) {
		panic("collection " + cid + " is already bound")
	}
	if v := bound.Get(id); v != nil {
		panic("store " + id + " is already bound to collection " + v.(string))
	}
	if info.MaxSupply != si.Slots {
		panic("maxSupply " + strconv.FormatInt(info.MaxSupply, 10) + " must equal the store's slots " +
			strconv.FormatInt(si.Slots, 10))
	}
	assertPayees(cid)
	bound.Set(id, cid)
	byCID.Set(cid, &binding{store: id})
	chain.Emit("StoreBound", "store", id, "cid", cid)
}

// Unbind releases the store while the collection is still a Draft.
// Creator only. Event StoreUnbound{store, cid}.
func Unbind(cur realm, cid string) {
	assertWallet(cur)
	info := core.Info(cid)
	assertUploadDraft(info, cid)
	if cur.Previous().Address() != info.Creator {
		panic("only the collection's creator can unbind its store")
	}
	v := byCID.Get(cid)
	if v == nil {
		panic("collection " + cid + " is not bound")
	}
	id := v.(*binding).store
	byCID.Remove(cid)
	bound.Remove(id)
	chain.Emit("StoreUnbound", "store", id, "cid", cid)
}

// Settle caches the permutation key once the collection is Final. Anyone
// may call it; it is deterministic (the salt is final) and idempotent, and
// it only saves read gas: the lazy path computes the same key.
// Event Settled{cid, key} (first call only).
func Settle(cur realm, cid string) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
	info := core.Info(cid)
	if info.EngineID != selfPath {
		panic("collection " + cid + " does not use the upload engine")
	}
	if info.State != types.StateFinal {
		panic("collection " + cid + " is not final yet")
	}
	v := byCID.Get(cid)
	if v == nil {
		panic("collection " + cid + " is not bound to a store")
	}
	b := v.(*binding)
	if b.key != "" {
		return
	}
	salt := provenanceSalt(core.Provenance(cid))
	if salt == "" {
		panic("collection " + cid + " has no final salt")
	}
	b.salt = salt
	b.key = media.PermKey(cid, salt)
	chain.Emit("Settled", "cid", cid, "key", b.key)
}

func assertWallet(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("call this directly from a wallet")
	}
	if !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func assertUploadDraft(info types.CollectionInfo, cid string) {
	if info.EngineID != selfPath {
		panic("collection " + cid + " does not use the upload engine")
	}
	if info.State != types.StateDraft {
		panic("collection " + cid + " is " + info.State.String() +
			"; stores are bound or unbound only while it is a draft (no token was ever minted)")
	}
}

// assertPayees refuses this realm and assets/v1 as primary or royalty
// payees (SA-L5: neither can ever spend a payment). Core already refuses
// itself, its sub-addresses, minters, the engine adapter and its siblings.
func assertPayees(cid string) {
	bad := []address{chain.PackageAddress(selfPath), chain.PackageAddress(assetsPath)}
	var addrs []address
	for _, p := range core.PrimaryPayees(cid) {
		addrs = append(addrs, p.Addr)
	}
	for _, part := range strings.Split(jsonStrField(core.Collection(cid), "royaltyPayees"), ",") {
		if a, _, ok := strings.Cut(part, ":"); ok {
			addrs = append(addrs, address(a))
		}
	}
	for _, a := range addrs {
		for _, b := range bad {
			if a == b {
				panic("payee " + a.String() + " is a platform realm that cannot spend; use a wallet")
			}
		}
	}
}

// jsonStrField reads a string field of core's JSON. Values written by
// safe.JSONWriter escape '"', so the key pattern cannot be forged by user text.
func jsonStrField(js, key string) string {
	pat := `"` + key + `":"`
	i := strings.Index(js, pat)
	if i < 0 {
		return ""
	}
	rest := js[i+len(pat):]
	j := strings.IndexByte(rest, '"')
	if j < 0 {
		return ""
	}
	return rest[:j]
}

// provenanceSalt is the final salt from core.Provenance JSON ("" before
// Final). The pattern `"salt":"` cannot be forged: JSONWriter escapes every
// '"' inside a secret.
func provenanceSalt(prov string) string {
	s := jsonStrField(prov, "salt")
	if !media.IsHex32(s) {
		return ""
	}
	return s
}

// parseParams accepts exactly "store:<id>" with a canonical decimal id.
func parseParams(p string) (string, bool) {
	if !strings.HasPrefix(p, "store:") {
		return "", false
	}
	id := p[len("store:"):]
	if id == "" || len(id) > 10 || id[0] == '0' {
		return "", false
	}
	for i := 0; i < len(id); i++ {
		if id[i] < '0' || id[i] > '9' {
			return "", false
		}
	}
	return id, true
}

func storeExists(id string) bool {
	n, err := strconv.ParseInt(id, 10, 64)
	return err == nil && n >= 1 && n <= assets.StoreCount()
}

// tidNum is the numeric token id, 0 for a non-canonical one.
func tidNum(tid string) int64 {
	if tid == "" || len(tid) > 12 || tid[0] == '0' {
		return 0
	}
	var n int64
	for i := 0; i < len(tid); i++ {
		c := tid[i]
		if c < '0' || c > '9' {
			return 0
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

// --- resolution ----------------------------------------------------------------

// resolved is one token's assignment.
type resolved struct {
	cid, tid      string
	info          types.CollectionInfo
	store         string
	si            media.StoreInfo
	key           string
	slot, edition int64
	art           media.Artwork
}

// coreResolve answers only core's own TokenURI/TokenTraits call for a
// Final, bound collection: CollectionID, params and seed must be exactly
// what core passes (§7 snipe resistance). Anything else gets the card.
func coreResolve(in engine.Input) (resolved, bool) {
	var r resolved
	if in.Params == "" || in.CollectionID == "0" {
		return r, false
	}
	v := byCID.Get(in.CollectionID)
	if v == nil {
		return r, false
	}
	b := v.(*binding)
	if in.Params != "store:"+b.store {
		return r, false
	}
	info := core.Info(in.CollectionID)
	if info.EngineID != selfPath || info.State != types.StateFinal || info.Params != in.Params {
		return r, false
	}
	salt := saltOf(in.CollectionID, b)
	if salt == "" || in.Seed != safe.Seed(in.CollectionID, in.TokenID, salt) {
		return r, false
	}
	n := tidNum(in.TokenID)
	if n < 1 || n > info.MaxSupply {
		return r, false
	}
	return assign(in.CollectionID, in.TokenID, n, info, b.store, assets.Info(b.store), keyOf(in.CollectionID, b, salt), nil), true
}

func saltOf(cid string, b *binding) string {
	if b.salt != "" {
		return b.salt
	}
	return provenanceSalt(core.Provenance(cid))
}

func keyOf(cid string, b *binding, salt string) string {
	if b.key != "" {
		return b.key
	}
	return media.PermKey(cid, salt)
}

// assign maps token n to its slot, artwork and edition. With a cache (trait
// batches) artworks are read once per batch and without their hashes/CID
// (assets.ArtworkMeta); without one the full record is read.
func assign(cid, tid string, n int64, info types.CollectionInfo, store string, si media.StoreInfo, key string,
	cache map[int64]media.Artwork,
) resolved {
	slot := media.Slot(key, si.Artworks, si.Slots, n)
	idx, edition := assets.SlotArtwork(store, slot)
	var a media.Artwork
	if cache != nil {
		if c, ok := cache[idx]; ok {
			a = c
		} else {
			a = assets.ArtworkMeta(store, idx)
			cache[idx] = a
		}
	} else {
		a = assets.ArtworkAt(store, idx)
	}
	return resolved{cid: cid, tid: tid, info: info, store: store, si: si, key: key, slot: slot, edition: edition, art: a}
}

func editionLabel(e, of int64) string {
	return strconv.FormatInt(e, 10) + "/" + strconv.FormatInt(of, 10)
}

func storageLabel(kind int) string {
	if kind == media.KindChain {
		return "On-chain"
	}
	return "IPFS"
}

// Package reader is the batch JSON read API for the frontend and the
// aggregator (design §2.5.6). It is private (re-deployable in place, no
// other realm may import it) and holds no state or money: everything comes
// from core, market and r/sys/users.
//
// Every string goes out through safe.JSONWriter, so stored text can never
// forge a record (RA H-1: the old TSV reader split on tabs and newlines).
// Art is never batched: one token per Art call, because SVG rendering is
// what exhausted the query gas in nftread1 (RA L-9).
package reader

import (
	"gno.land/r/sys/users"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/safe/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"
	upload "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/engines/upload"
	market "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/market/v1"
)

// Batch limits. Hypothesis (S-4): sized for the genesis engine under the
// public qeval gas cap; measure on Onyx and lower if a full page runs out.
const (
	MaxCards       = 50
	MaxTraitCounts = 500
	MaxStudio      = 200
	// Uploaded collections carry the creator's real trait names (up to 8 types
	// of 32 bytes); pages are smaller so the worst store the asset limits allow
	// stays <= 1B test gas per read (review UP-M1, zz_worst_gas_test.gno).
	MaxUploadCards       = 20
	MaxUploadTraitCounts = 200
)

// Cards is one gallery page: [{tid, owner, ownerName, traits, listing}] for
// tokens offset+1 … offset+limit (limit <= 50; <= 20 for uploaded
// collections). Burned tokens are skipped; listing is
// {id, price} or null. Uploaded collections carry the creator's real trait
// names (upload.TraitLists, one permutation key per page) instead of core's
// fixed engine slots.
func Cards(cid string, offset, limit int64) string {
	info := core.Info(cid)
	var upTraits map[string]string
	max := int64(MaxCards)
	if info.EngineID == upload.SelfPath() {
		max = MaxUploadCards
		upTraits = uploadTraits(cid, offset, clamp(limit, max))
	}
	w := &safe.JSONWriter{}
	w.BeginArray()
	for _, tid := range tokenRange(info.Minted, offset, limit, max) {
		owner, err := core.OwnerOf(cid, tid)
		if err != nil {
			continue // burned
		}
		w.BeginObject()
		w.StrField("tid", tid)
		w.StrField("owner", owner.String())
		w.StrField("ownerName", nameOf(owner))
		w.Key("traits")
		if upTraits != nil {
			w.Raw(upTraits[tid]) // JSON escaped once by the store (upload.TraitJSONLists)
		} else {
			writeTraits(w, core.TokenTraitList(cid, tid))
		}
		w.Key("listing")
		if id, price, ok := market.ActiveListing(cid, tid); ok {
			w.BeginObject()
			w.StrField("id", id)
			w.IntField("price", price)
			w.EndObject()
		} else {
			w.Raw("null")
		}
		w.EndObject()
	}
	w.EndArray()
	return w.String()
}

// TraitCounts counts trait values over tokens offset+1 … offset+limit:
// {"n": tokens counted, "counts": {type: {value: count}}} (limit <= 500;
// <= 200 for uploaded collections). Rarity % for a 1000-token collection
// takes two calls (five for an uploaded one). Before Final every token reports
// Status=Unrevealed.
func TraitCounts(cid string, offset, limit int64) string {
	info := core.Info(cid)
	c := newCounter()
	if info.EngineID == upload.SelfPath() {
		// creator-assigned tiers and real trait names, counted by the store
		// over integer ids (burned tokens skipped; order: Tier, the creator's
		// types, Edition, Storage)
		return upload.TraitCounts(cid, offset, clamp(limit, MaxUploadTraitCounts))
	}
	for _, tid := range tokenRange(info.Minted, offset, limit, MaxTraitCounts) {
		if _, err := core.OwnerOf(cid, tid); err != nil {
			continue
		}
		c.add(core.TokenTraitList(cid, tid))
	}
	return c.json()
}

// StudioTraits is TraitCounts for an engine and params over n sample seeds
// (engine.SampleSeed(from) …), for the Studio's rarity preview.
func StudioTraits(engineID, params string, from, n int64) string {
	if n <= 0 || n > MaxStudio {
		n = MaxStudio
	}
	if from < 0 {
		from = 0
	}
	c := newCounter()
	for i := from; i < from+n; i++ {
		c.add(core.EngineTraits(engineID, params, engine.SampleSeed(int(i))))
	}
	return c.json()
}

// Art is one token's data URI (placeholder before Final).
func Art(cid, tid string) string {
	uri, err := core.TokenURI(cid, tid)
	if err != nil {
		panic(err)
	}
	return uri
}

func Collections(offset, limit int64) string { return core.Collections(offset, limit) }

// SetComposition passes upload.SetComposition through: slots per
// creator-assigned tier and trait value over an uploaded collection's set.
func SetComposition(cid string) string { return upload.SetComposition(cid) }

// UploadStatus passes upload.Status through (mint gating, storage badge).
func UploadStatus(cid string) string { return upload.Status(cid) }

// Profile is {address, name, collections} for one address. A seller's
// listings come from the indexer (market "Listed"/"Cancelled" events):
// market/v1 keeps no per-seller index on chain (storage, M2).
func Profile(addr address) string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("address", addr.String())
	w.StrField("name", nameOf(addr))
	w.Key("collections")
	w.Raw(core.CollectionsByCreator(addr, 0, MaxCards))
	w.EndObject()
	return w.String()
}

// --- helpers -----------------------------------------------------------------

// nameOf is the r/sys/users name of addr, or "".
func nameOf(addr address) string {
	if u := users.ResolveAddress(addr); u != nil {
		return u.Name()
	}
	return ""
}

func uploadTraits(cid string, offset, limit int64) map[string]string {
	tids, lists := upload.TraitJSONLists(cid, offset, limit)
	out := make(map[string]string, len(tids))
	for i, tid := range tids {
		out[tid] = lists[i]
	}
	return out
}

func clamp(limit, max int64) int64 {
	if limit <= 0 || limit > max {
		return max
	}
	return limit
}

func tokenRange(minted, offset, limit, max int64) []string {
	if limit <= 0 || limit > max {
		limit = max
	}
	if offset < 0 {
		offset = 0
	}
	var out []string
	for n := offset + 1; n <= minted && n <= offset+limit; n++ {
		out = append(out, itoa(n))
	}
	return out
}

func writeTraits(w *safe.JSONWriter, ts []engine.Trait) {
	w.BeginArray()
	for _, t := range ts {
		w.BeginObject()
		w.StrField("trait_type", t.Type)
		w.StrField("value", t.Value)
		w.EndObject()
	}
	w.EndArray()
}

// counter keeps first-seen order so the JSON is deterministic.
type counter struct {
	n      int64
	types  []string
	values map[string][]string       // type -> values in first-seen order
	counts map[string]map[string]int64 // type -> value -> count
}

func newCounter() *counter {
	return &counter{values: map[string][]string{}, counts: map[string]map[string]int64{}}
}

func (c *counter) add(ts []engine.Trait) {
	c.n++
	for _, t := range ts {
		byValue, ok := c.counts[t.Type]
		if !ok {
			byValue = map[string]int64{}
			c.counts[t.Type] = byValue
			c.types = append(c.types, t.Type)
		}
		if _, seen := byValue[t.Value]; !seen {
			c.values[t.Type] = append(c.values[t.Type], t.Value)
		}
		byValue[t.Value]++
	}
}

func (c *counter) json() string {
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("n", c.n)
	w.Key("counts")
	w.BeginObject()
	for _, typ := range c.types {
		w.Key(typ)
		w.BeginObject()
		for _, v := range c.values[typ] {
			w.IntField(v, c.counts[typ][v])
		}
		w.EndObject()
	}
	w.EndObject()
	w.EndObject()
	return w.String()
}

func itoa(n int64) string { return safe.PadInt(n, 1) }

// Package gallery is the platform's gnoweb face (design §2.5.7): the
// product stays browsable on gno.land even without the website. It is
// private (re-deployable in place), read-only and holds nothing.
//
// Routes:
//
//	""                    latest collections
//	c/<cid>[?page=N]      one collection, 20 tokens per page
//	c/<cid>/t/<tid>       one token: art, traits, owner, listing, provenance
//	e/<engine pkgpath>    an engine's manifest and status
//	u/<name>              a registered user's collections and listings
//
// Every user-supplied string is rendered as plain text (plainText: RA M-9,
// SA-M4): no heading, link, image, HTML or autolink can come out of a name,
// description, trait or manifest field. Every list is paginated.
package gallery

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/sys/users"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/media/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/types/v1"
	assets "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/assets/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"
	upload "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/engines/upload"
	market "gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/market/v1"
)

const (
	pageSize   = 20
	homeLimit  = 20
	maxPageNum = 500
)

func Render(path string) string {
	route, query, _ := strings.Cut(path, "?")
	parts := strings.Split(route, "/")
	switch {
	case route == "":
		return home()
	case len(parts) == 2 && parts[0] == "c":
		return collectionPage(parts[1], pageFrom(query))
	case len(parts) == 4 && parts[0] == "c" && parts[2] == "t":
		return tokenPage(parts[1], parts[3])
	case len(parts) > 1 && parts[0] == "e":
		return enginePage(strings.TrimPrefix(route, "e/"))
	case len(parts) == 2 && parts[0] == "u":
		return userPage(parts[1])
	}
	return "# Not found\n\n[Back to the gallery](" + base() + ")\n"
}

func home() string {
	n := core.CollectionCount()
	out := ufmt.Sprintf("# Gallery\n\n%d collections. Art is computed on chain from each collection's engine and revealed seed.\n\n", n)
	for id := n; id >= 1 && id > n-homeLimit; id-- {
		info := core.Info(itoa(id))
		out += ufmt.Sprintf("- [%s](%s) — %s, %d/%d minted\n",
			plainText(info.Name), link("c/"+info.ID), info.State.String(), info.Minted, info.MaxSupply)
	}
	return out
}

func collectionPage(cid string, page int64) string {
	info := core.Info(cid)
	out := "# " + plainText(info.Name) + " (" + plainText(info.Symbol) + ")\n\n"
	if info.Description != "" {
		out += plainText(info.Description) + "\n\n"
	}
	out += ufmt.Sprintf("- State: **%s**, %d/%d minted, royalty %d bps\n", info.State.String(), info.Minted, info.MaxSupply, info.RoyaltyBps)
	out += "- Creator: " + who(info.Creator) + "\n"
	out += "- Engine: [" + plainText(info.EngineID) + "](" + link("e/"+info.EngineID) + ")\n"
	if info.Badge != "" {
		out += "- Provenance: **" + info.Badge + "** — " + fairness(cid) + "\n"
	}
	if info.EngineID == upload.SelfPath() {
		out += uploadCollectionLines(cid)
	}
	if f := market.Floor(cid); f > 0 {
		out += ufmt.Sprintf("- Floor: %d ugnot\n", f)
	}
	out += "\n## Tokens\n\n"
	first := (page-1)*pageSize + 1
	for n := first; n < first+pageSize && n <= info.Minted; n++ {
		tid := itoa(n)
		owner, err := core.OwnerOf(cid, tid)
		if err != nil {
			continue
		}
		line := "- [#" + tid + "](" + link("c/"+cid+"/t/"+tid) + ") owned by " + who(owner)
		if _, price, ok := market.ActiveListing(cid, tid); ok {
			line += ufmt.Sprintf(", listed at %d ugnot", price)
		}
		out += line + "\n"
	}
	if first+pageSize <= info.Minted {
		out += "\n[Next page](" + link(ufmt.Sprintf("c/%s?page=%d", cid, page+1)) + ")\n"
	}
	return out
}

func tokenPage(cid, tid string) string {
	info := core.Info(cid)
	owner, err := core.OwnerOf(cid, tid)
	if err != nil {
		return "# Token not found\n"
	}
	isUpload := info.EngineID == upload.SelfPath()
	uri, _ := core.TokenURI(cid, tid)
	var art media.Artwork
	var slot, edition int64
	ready := false
	if isUpload {
		ready, slot, edition, art = upload.Assignment(cid, tid)
		if ready && art.Kind == media.KindChain {
			uri = upload.TokenImage(cid, tid) // the stored file itself (data: URI, gnoweb img-src data:)
		}
	}
	out := "# " + plainText(info.Name) + " #" + tid + "\n\n"
	out += "![" + plainText(info.Name) + " #" + tid + "](" + sanitize.ImageURL(uri) + ")\n\n"
	out += "- Owner: " + who(owner) + "\n"
	if isUpload {
		out += uploadTokenLines(cid, ready, edition, art)
	}
	if id, price, ok := market.ActiveListing(cid, tid); ok {
		out += ufmt.Sprintf("- Listed: %d ugnot (listing %s)\n", price, id)
	}
	out += "\n## Traits\n\n"
	traits := core.TokenTraitList(cid, tid)
	if isUpload {
		traits = upload.TokenTraitList(cid, tid)
		out += "Tier and traits assigned by the creator.\n\n"
	}
	for _, t := range traits {
		out += "- " + plainText(t.Type) + ": " + plainText(t.Value) + "\n"
	}
	out += "\n## How to verify\n\n"
	if info.State != types.StateFinal {
		out += "The collection is not revealed yet; every token shows the same placeholder.\n"
		return out
	}
	if isUpload {
		return out + uploadVerifySteps(cid, tid, ready, slot, art)
	}
	out += "1. Read `Provenance(\"" + cid + "\")` on core from another RPC and recompute the commitments and the salt.\n"
	out += "2. Seed: `TokenSeed(\"" + cid + "\", \"" + tid + "\")` = sha256(\"" + "art|seed|v1|" + cid + "|" + tid + "|\" + salt).\n"
	out += "3. Render it yourself: `RenderWith(engine, params, seed)` must return this image.\n\n"
	out += "Provenance badge **" + info.Badge + "**, on-chain check: " + strconv.FormatBool(core.VerifyProvenance(cid)) +
		"; " + fairness(cid) + "\n"
	return out
}

// --- uploaded collections (docs/uploaded-collections.md §5.4, §9) -------------

// badgeLabel is the site's storage badge text (§9).
func badgeLabel(b string) string {
	switch b {
	case "onchain":
		return "On-chain"
	case "ipfs":
		return "IPFS · hash-locked"
	case "mixed":
		return "Mixed (on-chain and IPFS)"
	case "computed":
		return "Computed on-chain"
	}
	return "Not ready"
}

func uploadCollectionLines(cid string) string {
	ready, reason, store, badge := upload.Readiness(cid)
	out := "- Storage: **" + badgeLabel(badge) + "**\n"
	if !ready {
		out += "- **Not ready (" + reason + ")**: the artwork set is not locked to this collection; do not mint.\n"
	}
	if store == "" {
		return out
	}
	si := assets.Info(store)
	out += ufmt.Sprintf("- Artwork set: store %s, %d artworks, %d slots (%d on-chain, %d IPFS); verifiable on chain / IPFS\n",
		store, si.Artworks, si.Slots, si.OnchainN, si.IPFSN)
	tiers, slots, untiered := assets.TierSlots(store)
	if len(tiers) > 0 {
		var parts []string
		for i := len(tiers) - 1; i >= 0; i-- { // high -> low, like a drop table
			if slots[i] > 0 {
				parts = append(parts, ufmt.Sprintf("%d %s", slots[i], plainText(tiers[i])))
			}
		}
		if untiered > 0 {
			parts = append(parts, ufmt.Sprintf("%d untiered", untiered))
		}
		out += "- Set composition (creator-assigned tiers, slots of " + itoa(si.Slots) + "): " +
			strings.Join(parts, " · ") + "\n"
	}
	return out
}

func uploadTokenLines(cid string, ready bool, edition int64, a media.Artwork) string {
	_, _, _, badge := upload.Readiness(cid)
	out := "- Storage: **" + badgeLabel(badge) + "**\n"
	if !ready {
		return out
	}
	if a.Title != "" {
		out += "- Artwork: " + plainText(a.Title) + "\n"
	}
	if a.Tier != "" {
		out += "- Tier: **" + plainText(a.Tier) + "** (assigned by the creator)\n"
	}
	if a.Editions > 1 {
		out += ufmt.Sprintf("- Edition %d of %d\n", edition, a.Editions)
	}
	out += ufmt.Sprintf("- File: %s, %d bytes, sha256 `%s`\n", media.MimeType(a.Mime), a.Size, a.SHA256)
	if a.Kind != media.KindChain {
		// never a remote image (SA-M4): the address is escaped text
		out += "- IPFS: " + plainText("ipfs://"+a.CID) + " (fetch it from any gateway and check the sha256)\n"
	}
	return out
}

func uploadVerifySteps(cid, tid string, ready bool, slot int64, a media.Artwork) string {
	if !ready {
		return "This uploaded collection is not bound to a sealed artwork set; no artwork is assigned.\n"
	}
	store := upload.StoreOf(cid)
	out := "1. Read `Provenance(\"" + cid + "\")` on core from another RPC and recompute the commitments and the salt.\n"
	out += "2. Key: `K = sha256(\"art|upload|perm|v1|" + cid + "|\" + salt)`, slot: `Permute(K, slots, " + tid +
		" - 1)` (media/v1; a single-artwork store uses slot = " + tid + " - 1).\n"
	out += ufmt.Sprintf("3. `SlotArtwork(\"%s\", %d)` on the asset store gives artwork %d; its sha256 must be the file's.\n",
		store, slot, a.Index)
	out += "\nProvenance badge **" + core.Info(cid).Badge + "**, on-chain check: " +
		strconv.FormatBool(core.VerifyProvenance(cid)) + "; " + fairness(cid) + "\n"
	return out
}

// fairness never calls a collection "verified" unless it is a fair launch
// (core.FairLaunch): a consistent record is not enough when one party could
// choose the map (SA-M2).
func fairness(cid string) string {
	if core.FairLaunch(cid) {
		return "fair launch, verified on chain"
	}
	if !core.VerifyProvenance(cid) {
		return "NOT verified: the provenance record does not check out"
	}
	return "not a fair launch: one party could choose the map (record consistent)"
}

// plainText renders user text as inert markdown: sanitize.InlineText escapes
// every inline-active character (\ * _ [ ] ( ) ~ > - + . ! ` # < &) and folds
// newlines, and escaping ':' breaks bare-URL autolinks ("https\://…"), which
// InlineText leaves alone (SA-M4).
func plainText(s string) string {
	return strings.ReplaceAll(sanitize.InlineText(s), ":", "\\:")
}

func enginePage(id string) string {
	m := core.EngineManifest(id)
	out := "# Engine " + plainText(m.Name) + " " + plainText(m.Version) + "\n\n"
	out += "- Realm: " + sanitize.InlineCode(id) + "\n"
	out += "- Author: " + who(m.Author) + "\n"
	out += "- Status: **" + core.EngineStatus(id) + "**, sample fingerprint intact: " + strconv.FormatBool(core.VerifyEngine(id)) + "\n"
	out += "- License: " + plainText(m.License) + "\n"
	out += "- Traits: " + plainText(strings.Join(m.TraitTypes, ", ")) + "\n\n"
	if m.Description != "" {
		out += plainText(m.Description) + "\n"
	}
	return out
}

func userPage(name string) string {
	u, _ := users.ResolveName(name)
	if u == nil {
		return "# Unknown user\n"
	}
	addr := u.Addr()
	return "# @" + sanitize.InlineText(u.Name()) + "\n\n`" + addr.String() + "`\n\n" +
		"Collections and listings of this address: reader realm, `Profile(" + addr.String() + ")`.\n"
}

// who renders an address as its r/sys/users name when it has one.
func who(addr address) string {
	if u := users.ResolveAddress(addr); u != nil {
		return "[@" + sanitize.InlineText(u.Name()) + "](/u/" + sanitize.InlineText(u.Name()) + ")"
	}
	return "`" + addr.String() + "`"
}

func pageFrom(query string) int64 {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			if n, err := strconv.ParseInt(strings.TrimPrefix(kv, "page="), 10, 64); err == nil && n >= 1 && n <= maxPageNum {
				return n
			}
		}
	}
	return 1
}

// selfPath is captured at deploy; links are gnoweb paths without the domain.
var selfPath string

func init(cur realm) {
	selfPath = cur.PkgPath()
}

func base() string {
	return strings.TrimPrefix(selfPath, "gno.land")
}

func link(route string) string { return base() + ":" + route }

func itoa(n int64) string { return strconv.FormatInt(n, 10) }
